-- =============================================================================
-- PM Quiz Questions — Modules 10–18 (pm-v1)
-- Course: AI Project Manager & Delivery Leader
-- 15 questions per module = 135 questions total
-- Competency slugs: pm:quality, pm:agile, pm:change-management,
--   pm:portfolio, pm:tech-delivery, pm:analytics, pm:executive-comms,
--   pm:governance, pm:career
-- Apply: paste into Supabase SQL Editor → Run
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.fill_pm_exam_b(p_order int, p_questions jsonb)
RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  cid uuid; ch uuid; qz uuid; rec jsonb; i int := 0;
BEGIN
  SELECT id INTO cid FROM public.courses
    WHERE title = 'AI Project Manager & Delivery Leader'
      AND curriculum_version = 'pm-v1';
  IF cid IS NULL THEN RAISE NOTICE 'PM course not found'; RETURN; END IF;

  SELECT id INTO ch FROM public.chapters
    WHERE course_id = cid AND order_index = p_order;
  IF ch IS NULL THEN RAISE NOTICE 'Chapter at order_index % not found', p_order; RETURN; END IF;

  SELECT id INTO qz FROM public.quizzes
    WHERE chapter_id = ch AND quiz_type = 'chapter_end';
  IF qz IS NULL THEN RAISE NOTICE 'No chapter_end quiz for module %', p_order; RETURN; END IF;

  IF EXISTS (SELECT 1 FROM public.quiz_questions WHERE quiz_id = qz) THEN
    RAISE NOTICE 'Module % already has questions — skipping', p_order; RETURN;
  END IF;

  FOR rec IN SELECT * FROM jsonb_array_elements(p_questions) LOOP
    i := i + 1;
    INSERT INTO public.quiz_questions
      (quiz_id, question_text, options, correct_answer_index, explanation,
       order_index, competency, translations)
    VALUES (
      qz,
      rec->>'q',
      rec->'o',
      (rec->>'a')::int,
      rec->>'e',
      i,
      rec->>'c',
      '{}'::jsonb
    );
  END LOOP;
  RAISE NOTICE 'Module %: inserted % questions', p_order, i;
END;
$fn$;

SELECT pg_temp.fill_pm_exam_b(10, '[
{"q":"A PM is planning quality activities for a complex software release. She must decide whether to invest more in code reviews and static analysis or in post-release defect resolution. According to the Cost of Quality framework, code reviews and static analysis are classified as which category?","o":["Prevention costs","Appraisal costs","Internal failure costs","External failure costs"],"a":0,"e":"Prevention costs are incurred to avoid defects before they occur. Code reviews and static analysis are classic prevention activities. Appraisal costs cover inspection and testing of completed work. Internal failure costs arise from defects caught before release; external failure costs arise after the customer receives the product.","c":"pm:quality"},
{"q":"During a sprint review, the QA lead presents a control chart showing that five consecutive data points fall on the same side of the mean. No points exceed the control limits. What is the correct interpretation and recommended action?","o":["The process is out of control due to a non-random run rule; investigate the assignable cause","The process is in control because no points exceed the upper or lower control limits","The process is showing natural variation; no action is needed until a point exceeds a limit","The chart is inconclusive; collect more data before making any judgment"],"a":0,"e":"Control chart run rules state that seven (or in some interpretations five or six) consecutive points on one side of the mean indicate a non-random pattern and an assignable (special) cause, even when no point exceeds the control limits. The PM should investigate and correct the root cause immediately rather than wait for a limit violation.","c":"pm:quality"},
{"q":"Quality Assurance (QA) and Quality Control (QC) are related but distinct disciplines. Which statement most accurately distinguishes them in a project context?","o":["QA audits processes to prevent defects; QC inspects outputs to detect defects","QA tests finished products; QC defines the standards for those tests","QA is performed by an external auditor; QC is performed by the project team","QA applies only to software projects; QC applies to manufacturing"],"a":0,"e":"QA is a proactive, process-oriented discipline focused on improving the processes that produce deliverables, thereby preventing defects. QC is a reactive, product-oriented discipline that inspects completed work to identify defects. Both can be performed by internal or external parties on any type of project.","c":"pm:quality"},
{"q":"A team performing root-cause analysis on a surge in production defects constructs a fishbone (Ishikawa) diagram. They identify six potential cause categories. What is the primary purpose of this diagram in the quality management process?","o":["To visually map potential causes of a problem back to their source categories so the team can prioritize investigation","To track the frequency of each defect type so the most common can be addressed first","To chart process measurements over time and detect when the process becomes unstable","To document the cost impact of each defect category for the cost-of-quality register"],"a":0,"e":"The Ishikawa (fishbone or cause-and-effect) diagram structures the brainstorming of potential causes into categories (e.g., People, Process, Equipment, Materials, Environment, Measurement) and connects them visually to the effect. Its purpose is root-cause discovery, not frequency tracking (that is Pareto), time-series monitoring (that is a control chart), or financial quantification.","c":"pm:quality"},
{"q":"After analyzing six months of production defect data, a team plots defect frequency by category and finds that 3 of 12 defect types account for 78% of all defects. Which quality tool and principle directly supports focusing remediation effort on those three categories first?","o":["Pareto chart applying the 80/20 principle","Control chart applying Western Electric run rules","Scatter diagram applying correlation analysis","Histogram applying normal distribution assumptions"],"a":0,"e":"A Pareto chart ranks defect categories by frequency (or cost) and applies the Pareto principle — roughly 80% of effects come from 20% of causes. Focusing on the vital few categories produces the greatest quality improvement for the effort invested.","c":"pm:quality"},
{"q":"A manufacturing PM is leading a process improvement initiative using DMAIC. The team has finished documenting current process performance and identifying the gap between current and target sigma levels. Which DMAIC phase have they just completed?","o":["Measure","Define","Analyze","Improve"],"a":0,"e":"In DMAIC (Define, Measure, Analyze, Improve, Control), the Measure phase involves collecting data on current process performance and establishing baseline metrics. Define frames the problem and project charter; Analyze identifies root causes; Improve implements solutions; Control sustains gains.","c":"pm:quality"},
{"q":"A PM discovers that testers are approving user stories without documented acceptance criteria because the team is under schedule pressure. Which quality management response is most appropriate?","o":["Escalate to the sponsor and enforce acceptance criteria as a Definition of Done gate before any story is accepted","Allow the practice temporarily but increase the post-release defect budget to compensate","Reduce the scope of testing to match available time and document the risk","Transfer the quality risk to the customer by including a disclosure in release notes"],"a":0,"e":"Acceptance criteria are the contractual quality threshold for each story. Bypassing them accumulates technical and quality debt and exposes the project to external failure costs. Enforcing criteria as a DoD gate is the correct preventive action. The other options defer or transfer risk rather than addressing its root cause.","c":"pm:quality"},
{"q":"An AI-assisted quality monitoring system flags a batch of transactions as anomalous with 94% model confidence. The human QA analyst reviews a sample and finds no actual defects. What is the most appropriate next step?","o":["Investigate whether the model is generating false positives due to distributional shift in the input data","Accept the AI flag and quarantine the full batch to avoid external failure risk","Disable the AI monitor and revert to manual inspection until the model is retrained","Log the discrepancy as a known issue and continue without changing the threshold"],"a":0,"e":"A high false-positive rate with 94% model confidence but no confirmed defects is a classic symptom of distributional shift — the real-world data has drifted from the training distribution. The correct action is to investigate and recalibrate before either blindly acting on flags or abandoning the tool.","c":"pm:quality"},
{"q":"In Lean quality thinking, which of the following activities is considered ''muda'' (pure waste) that should be eliminated first?","o":["Waiting time when a deliverable sits in a queue between process steps","Rework required to correct a defect found in QC inspection","Overproduction of documentation not consumed by any stakeholder","All of the above are forms of muda that Lean targets for elimination"],"a":3,"e":"Lean identifies seven classic wastes (muda): defects, overproduction, waiting, non-utilized talent, transportation, inventory, and excess processing. Waiting between steps, rework from defects, and unused documentation (overproduction) are all direct examples. A PM applying Lean prioritizes eliminating these wastes to improve flow and quality simultaneously.","c":"pm:quality"},
{"q":"A PM is reviewing a process capability report that shows Cpk = 0.65 for a critical manufacturing dimension. What does this indicate and what action is warranted?","o":["The process is not capable of meeting specification limits; the PM should initiate an improvement project to reduce process variation or re-center the mean","The process is highly capable; a Cpk above 0.5 is considered world-class performance","The process is marginally capable; no action is needed unless Cpk falls below 0.5","Cpk measures cost of quality, not process capability; the PM should consult a different metric"],"a":0,"e":"Cpk measures how many standard deviations the process mean is from the nearest specification limit, adjusted for centering. A Cpk of 1.33 is generally the minimum for a capable process; 0.65 means the process is producing a significant percentage of out-of-specification output. Immediate improvement is warranted.","c":"pm:quality"},
{"q":"A PM must decide whether to halt delivery of a software release after QC testing reveals a defect escape rate of 4.2% — above the 2% threshold in the quality management plan. The release is scheduled for tomorrow and the sponsor is pushing to proceed. What is the correct course of action?","o":["Present the evidence to the sponsor: the defect rate exceeds the agreed threshold, which triggers the halt-delivery protocol defined in the quality plan","Proceed with release and issue a patch within 48 hours to minimize schedule impact","Reduce the threshold in the quality management plan to 5% to accommodate the current results","Deliver to a pilot group only and suppress the defect rate figure from the release notes"],"a":0,"e":"The quality management plan establishes the defect threshold as an objective, evidence-based gate. When the gate is not met, the protocol must be followed regardless of schedule pressure. The PM''s role is to present the data transparently and enforce the agreed gate. Retroactively changing thresholds or withholding data undermines quality governance.","c":"pm:quality"},
{"q":"During a Six Sigma project, the Black Belt asks the PM to map every step in the current order-fulfillment process, classify each step as value-added or non-value-added, and calculate the process cycle efficiency. Which tool is being requested?","o":["Value stream map","SIPOC diagram","Failure Mode and Effects Analysis (FMEA)","Affinity diagram"],"a":0,"e":"A value stream map visualizes the entire flow of materials and information, tags each step as value-added or non-value-added (waste), and captures time data to calculate process cycle efficiency (value-added time / total lead time). SIPOC gives a high-level process overview; FMEA assesses failure risks; affinity diagrams organize qualitative data.","c":"pm:quality"},
{"q":"A PM notices that the test team is consistently finding the same class of SQL injection vulnerabilities in sprint-end builds despite developer awareness training six months ago. Applying the quality management principle of prevention over inspection, what is the most effective intervention?","o":["Integrate automated static analysis security testing (SAST) into the CI pipeline so vulnerabilities are caught at commit time, before code reaches QC","Add SQL injection to the QC checklist so testers can flag it more efficiently","Schedule quarterly refresher training sessions on secure coding practices","Assign a dedicated security tester to review every pull request manually"],"a":0,"e":"Prevention over inspection means moving quality gates as early as possible in the process (''shift left''). Embedding SAST in the CI pipeline catches SQL injection at the moment of code commit — before the defect can propagate to testing or production. Training alone has already proven insufficient; manual PR review is appraisal, not prevention.","c":"pm:quality"},
{"q":"An organization''s quality audit reveals that defect containment cost (internal failure) averages $120K per quarter while warranty and customer-complaint costs (external failure) average $340K per quarter. What does this cost-of-quality profile indicate about the organization''s quality system?","o":["The organization is under-investing in prevention and appraisal; defects are escaping to customers at high cost","The organization''s QC is highly effective because most defects are caught internally before reaching customers","The ratio is typical; external failure costs are always higher than internal failure costs in software","The organization should reduce internal QC spending to lower overall cost of quality"],"a":0,"e":"A high external-failure cost relative to internal failure cost signals that the quality system is not catching defects before they reach the customer. The cost-of-quality model predicts that increasing investment in prevention (and to a lesser extent appraisal) will reduce both internal and especially external failure costs, lowering total cost of quality.","c":"pm:quality"},
{"q":"A PM is defining the test strategy for a regulatory-compliance system. Stakeholders disagree on whether end-to-end integration tests or unit tests should receive the majority of the testing budget. Which framing best guides the decision?","o":["Apply a risk-based test strategy: allocate more testing effort to components where defects would have the highest compliance impact and detection difficulty","Maximize unit test coverage first because unit tests are cheapest to run and catch defects earliest","Prioritize end-to-end tests because regulators care about system behavior, not individual functions","Split the budget equally to ensure balanced coverage across all test levels"],"a":0,"e":"A risk-based test strategy allocates effort proportional to the probability and impact of failure in each component. For a compliance system, the highest-risk paths — those whose failure would cause a regulatory breach — should receive the most rigorous testing, regardless of whether those paths are best covered by unit, integration, or end-to-end tests.","c":"pm:quality"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(11, '[
{"q":"In Scrum, the Sprint Retrospective is time-boxed to a maximum of three hours for a one-month sprint. A team member proposes skipping the retrospective to recover schedule time lost during the sprint. What is the PM/Scrum Master''s most appropriate response?","o":["Protect the retrospective: it is the primary mechanism for process improvement and skipping it accumulates team debt that compounds over future sprints","Agree to skip this one retrospective but require a longer one next sprint to compensate","Allow the team to vote on whether to hold it; Scrum events are guidelines, not mandates","Replace the retrospective with a 15-minute async survey to save time while maintaining the spirit of the event"],"a":0,"e":"The Sprint Retrospective is one of Scrum''s five formal events and is the team''s dedicated inspect-and-adapt moment for the process itself. Skipping it removes the improvement loop that makes Scrum self-correcting. Schedule pressure is precisely when teams most need to examine their process, not least. The Scrum Master''s duty is to protect and facilitate the event.","c":"pm:agile"},
{"q":"A Kanban team has set a WIP limit of 3 for the ''In Development'' column. A senior developer asks to pull a fourth item because she has spare capacity while waiting for code review on her current item. What is the correct Kanban response?","o":["Respect the WIP limit; the developer should help clear the code-review bottleneck rather than pull new work","Allow the exception because the developer has genuine capacity and idle resources are waste","Raise the WIP limit to 4 permanently to reflect the team''s true capacity","Move the blocked item directly to ''Done'' to free the slot before pulling new work"],"a":0,"e":"WIP limits exist to expose bottlenecks and create pull pressure toward completing work rather than starting it. When a developer is blocked waiting for code review, the correct Lean/Kanban response is to swarm the bottleneck — help review the waiting item — rather than start new work that will further clog the system. Raising WIP limits to accommodate blocking undermines the tool''s purpose.","c":"pm:agile"},
{"q":"A team''s sprint velocity has averaged 42 points over the last four sprints but drops to 27 in Sprint 9 with no personnel change. Which investigation sequence follows agile empiricism most rigorously?","o":["Hold the Sprint Retrospective and inspect the data: examine what changed in Sprint 9 — dependencies, unplanned work, scope churn, or technical impediments — before drawing conclusions","Reduce the Sprint 10 commitment to 27 points and treat the drop as the new baseline","Assign root-cause analysis to the Scrum Master and exclude the team to avoid bias","Add two developers for Sprint 10 to restore throughput while the cause is investigated"],"a":0,"e":"Agile empiricism demands transparency, inspection, and adaptation based on evidence. A single-sprint velocity drop should be inspected through the retrospective lens — examining what actually happened — before any capacity or process change is made. Immediately rebaselining or adding staff without understanding the cause may mask the real problem.","c":"pm:agile"},
{"q":"Cycle time and lead time are both flow metrics used in Kanban. A team''s average lead time is 18 days but average cycle time is 4 days. What does this gap most likely indicate?","o":["Work items spend significant time waiting in queues before active work begins, suggesting a prioritization or pull-system problem","The team is highly efficient because cycle time is much shorter than lead time","Lead time and cycle time should be equal in a healthy Kanban system; the gap signals a data error","The team needs to increase WIP limits to reduce the waiting time between stages"],"a":0,"e":"Lead time measures from the moment work is requested (enters the backlog) to delivery. Cycle time measures from when active work begins to delivery. A large lead-time-to-cycle-time gap means items wait a long time before the team starts them — revealing a prioritization, queue management, or demand-capacity imbalance problem. Increasing WIP limits would make it worse, not better.","c":"pm:agile"},
{"q":"An organization is scaling agile across 8 teams building the same product platform. The architecture team warns of integration conflicts arising from independent team backlogs. Which scaling framework directly addresses this through a shared ''Program Increment'' planning event?","o":["SAFe (Scaled Agile Framework)","LeSS (Large-Scale Scrum)","Nexus","Disciplined Agile Delivery (DAD)"],"a":0,"e":"SAFe''s PI (Program Increment) Planning is a cadence-based, face-to-face event where all teams on an Agile Release Train plan together, align on a shared PI objective, identify dependencies, and resolve conflicts. LeSS and Nexus also address scaling but do not feature the PI Planning ceremony as a core mechanism. DAD is a toolkit, not a prescriptive framework.","c":"pm:agile"},
{"q":"A Product Owner on a hybrid project is being pressured by a business stakeholder to add a high-priority feature to the current sprint that is already committed. The PM supports the Product Owner''s decision to defer the item to the next sprint backlog. Which principle justifies this position?","o":["Sprint scope is protected once committed; inserting unplanned work mid-sprint undermines the sprint goal and team predictability","The Product Owner must always prioritize stakeholder requests over sprint commitments to maintain business relationships","Hybrid projects should follow waterfall scope-change procedures, which allow mid-sprint changes with a signed change order","The PM should mediate by splitting the feature into a smaller story that fits the remaining sprint capacity"],"a":0,"e":"Once a sprint goal and commitment are set, the Scrum framework protects the team from mid-sprint scope insertion. Injecting high-priority work destroys predictability and invalidates the sprint goal. The correct response is to add the item to the top of the product backlog and pull it into the next sprint. The PM''s role in a hybrid environment is to shield agile ceremonies from waterfall-style scope-change pressure.","c":"pm:agile"},
{"q":"In a hybrid delivery model for a government IT program, regulatory milestones require fixed delivery dates and formal documentation, while the development team uses two-week Scrum sprints. Which approach best bridges these two operating models?","o":["Define a waterfall phase-gate roadmap at the program level with fixed milestone dates, while allowing the delivery team to use Scrum within each phase to plan and execute work","Abandon Scrum and revert to waterfall for all regulatory-facing work to ensure documentation compliance","Run two parallel tracks: one pure Scrum track and one pure waterfall track, managed independently","Convert all sprints to fixed-scope iterations that mirror waterfall stages to satisfy both models simultaneously"],"a":0,"e":"Hybrid delivery separates cadence from governance: program-level milestones provide the predictability required by regulatory stakeholders, while sprint-level agility enables the team to adapt within each phase. This is the core pattern of many hybrid frameworks (PRINCE2 Agile, SAFe). Running parallel independent tracks or eliminating Scrum both sacrifice the benefits of one model.","c":"pm:agile"},
{"q":"A stakeholder who has always relied on Gantt charts asks the PM to produce a traditional project schedule for an agile delivery program. The PM wants to remain responsive without abandoning agility. What is the most appropriate response?","o":["Create a release roadmap with milestone-level dates derived from velocity and backlog estimates, and offer a Gantt view of the program-level phases — not sprint-level tasks","Refuse and explain that Gantt charts are incompatible with agile and the stakeholder must learn to read a product roadmap","Produce a detailed Gantt chart for every sprint task to satisfy the request, reverting the team to waterfall task decomposition","Tell the stakeholder that dates cannot be given in agile and that value delivery is the only meaningful metric"],"a":0,"e":"Stakeholder responsiveness is an agile value. A release roadmap with milestone-level Gantt-style visualization satisfies the stakeholder''s legitimate need for schedule visibility without imposing waterfall task management on the team. Refusing outright ignores a valid stakeholder need; producing sprint-level Gantt charts reintroduces waterfall discipline through the back door.","c":"pm:agile"},
{"q":"The Nexus framework extends Scrum for 3–9 teams working on a single product. What is the primary artifact that Nexus adds to the standard Scrum set to manage cross-team integration?","o":["The Nexus Sprint Backlog, which identifies cross-team dependencies and the integration work required each sprint","The Program Increment (PI) Objectives, which align all teams to a shared quarterly commitment","The Portfolio Kanban board, which visualizes work items across all teams in a single flow","The Release Train Engineer role, which replaces the Scrum Master for integrated delivery"],"a":0,"e":"Nexus introduces three artifacts beyond standard Scrum: the Nexus Goal, the Nexus Sprint Backlog (which surfaces dependencies and integration tasks across teams), and the Integrated Increment. The PI Objectives and Release Train Engineer are SAFe constructs; the Portfolio Kanban is a SAFe portfolio-layer tool.","c":"pm:agile"},
{"q":"A Scrum team consistently fails to complete the sprint goal despite committing to fewer story points each sprint. The Scrum Master notices that stories are frequently ''done'' in development but waiting in ''testing'' at sprint end. What is the most effective structural fix?","o":["Redefine the team''s workflow so testers are pulled into stories during development rather than after, making testing a continuous activity within the sprint","Reduce the number of stories per sprint further until the team can complete all testing within the timebox","Hire additional testers to match the development throughput and eliminate the testing queue","Move testing to a hardening sprint at the end of each program increment to avoid mid-sprint bottlenecks"],"a":0,"e":"The testing bottleneck is a flow problem caused by sequential handoffs within the sprint. The fix is cross-functional collaboration: testers join development on each story (BDD, pair testing, continuous integration) so testing happens in parallel with development. Reducing commitment only masks the bottleneck; adding testers without changing the workflow perpetuates the sequential model; hardening sprints are an anti-pattern that defers integration risk.","c":"pm:agile"},
{"q":"In LeSS (Large-Scale Scrum), one Product Owner serves all teams. How does LeSS handle the backlog refinement challenge that arises when multiple teams need to work on different parts of the product?","o":["Multi-team refinement sessions allow all affected teams to refine backlog items together, and teams self-select which items to work on based on expertise and capacity","Each team has its own Product Owner who owns a portion of the backlog and prioritizes independently","A Release Train Engineer coordinates backlog distribution and assigns work packages to each team","Teams pull from separate mini-backlogs that are synchronized to the main backlog monthly"],"a":0,"e":"LeSS maintains a single Product Owner and a single Product Backlog for the entire product. Multi-team refinement (''Overall Product Backlog Refinement'' and ''Multi-Team PBR'') brings representatives from multiple teams together to clarify and split items, after which teams self-select what to work on. Separate Product Owners per team is the LeSS Huge variant for very large programs.","c":"pm:agile"},
{"q":"Capacity planning for a Scrum team must account for time lost to holidays, planned leave, and recurring ceremonies. A 5-person team each has 10 working days in the sprint. Two members will each be absent 2 days; ceremonies consume approximately 12 person-hours total. If each team member works 8 hours per day, what is the team''s available development capacity in hours?","o":["356 hours","368 hours","400 hours","332 hours"],"a":0,"e":"Total hours = 5 members × 10 days × 8 hrs = 400 hrs. Subtract absence: 2 members × 2 days × 8 hrs = 32 hrs lost. Net = 368 hrs. Subtract ceremony overhead: 368 − 12 = 356 hrs available for development. Accurate capacity planning prevents over-commitment and protects sprint goal attainability.","c":"pm:agile"},
{"q":"A PM leading an agile transformation notices that the team''s daily stand-up has evolved into a 45-minute status report meeting where the Scrum Master updates a spreadsheet while team members wait. What is the most accurate diagnosis and corrective action?","o":["The stand-up has regressed to a waterfall status meeting anti-pattern; the Scrum Master should refocus it on the three questions (what did I do, what will I do, what blocks me) and timebox it to 15 minutes","The stand-up is too short by design; 45 minutes is appropriate for a team of 7 or more members","The meeting should be eliminated and replaced with a daily async update tool to save time","The Scrum Master is correctly playing a reporting role; the issue is that the meeting needs better facilitation, not a shorter timebox"],"a":0,"e":"The Daily Scrum is a 15-minute team self-coordination event, not a status report for management. When it becomes a reporting ceremony facilitated upward, it is a common anti-pattern that destroys psychological safety and wastes team time. The fix is to return to the three questions, have the team speak to each other (not to the Scrum Master), and rigorously enforce the timebox.","c":"pm:agile"},
{"q":"A Product Owner wants to measure whether the team is delivering value, not just completing stories. She proposes tracking ''outcome velocity'' — the rate at which delivered features produce measurable business results — rather than story point velocity. What does this proposal reflect?","o":["A shift from output-focused to outcome-focused measurement, consistent with modern agile thinking about value delivery","An anti-pattern that replaces objective capacity data with lagging business metrics that the team cannot directly control","A misapplication of velocity; story points are already a proxy for business value, so the proposal is redundant","A SAFe-specific metric that is only valid when teams are organized as an Agile Release Train"],"a":0,"e":"Modern agile frameworks (including the Agile Manifesto, OKRs, and Evidence-Based Management) distinguish between output (features delivered) and outcome (value realized by customers). Outcome velocity is a legitimate evolution that keeps the team focused on why they are building, not just how much. Story points measure effort/complexity, not business value — so the proposal is not redundant.","c":"pm:agile"},
{"q":"A PM in a hybrid program is asked to set the sprint goal for the upcoming sprint because the Product Owner is on leave. What is the most appropriate course of action?","o":["Appoint a delegate Product Owner with sufficient product knowledge and authority to set the sprint goal; the PM should facilitate, not own, the product direction","Set the sprint goal based on the project plan milestones and inform the team","Allow the development team to self-organize and set their own sprint goal without Product Owner involvement","Postpone the sprint start until the Product Owner returns to maintain accountability"],"a":0,"e":"The Product Owner role owns the product backlog and the sprint goal — this accountability cannot be delegated to the PM, who has a different remit. The correct action is to designate a qualified Product Owner proxy (delegate) with real decision-making authority. The PM facilitating the goal-setting process is appropriate; the PM unilaterally setting the goal is not.","c":"pm:agile"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(12, '[
{"q":"A large-scale ERP implementation is six weeks from go-live. The head of finance — a critical stakeholder — has not responded to meeting invitations or reviewed any deliverables in three weeks. Using the ADKAR model, what is the most likely gap and what intervention addresses it?","o":["Awareness or Desire gap: the sponsor has not internalized the personal impact of the change; schedule a one-on-one to surface concerns and re-establish personal commitment","Ability gap: the sponsor lacks the skills to use the new system; arrange dedicated training sessions before go-live","Reinforcement gap: post-implementation incentives are not yet in place; commit to a reward structure for early adoption","Knowledge gap: the sponsor does not understand the implementation plan; share a detailed Gantt chart"],"a":0,"e":"Silence from a previously engaged sponsor most commonly signals an Awareness or Desire problem — they either do not understand the personal implications of the change or have lost commitment, often due to political, budget, or priority shifts. The first intervention is a direct conversation to surface the real concern. Ability and Knowledge gaps typically surface as questions or requests for help, not silence.","c":"pm:change-management"},
{"q":"Kotter''s 8-step change model begins with ''Create a Sense of Urgency.'' A PM is launching a digital transformation program and the CEO wants to skip this step because the organization already approved the budget. What risk does skipping this step most directly create?","o":["Middle managers and front-line staff who did not participate in the budget decision will lack the motivation to change their behaviors, creating passive resistance that erodes adoption","The program will exceed its budget because urgency drives cost discipline","The guiding coalition in Step 2 will be too large without urgency to filter committed members","Regulatory compliance will be at risk because urgency is required for sign-off on change controls"],"a":0,"e":"Budget approval from executives does not guarantee behavioral change throughout the organization. Kotter''s model recognizes that without a widely felt sense of urgency — understood and felt by the people who must change — the transformation will stall at the middle and front-line levels through apathy or passive resistance. The PM must build urgency across all affected levels, not just the executive suite.","c":"pm:change-management"},
{"q":"A PM''s change impact assessment reveals that the proposed process change will affect 340 customer-service agents'' daily workflows, requiring them to switch between three systems that are currently siloed. The ADKAR model''s ''Ability'' element specifically addresses which risk?","o":["The risk that employees understand and want the change but cannot perform the new behaviors due to skill gaps, tool complexity, or process barriers","The risk that employees have not been informed that the change is happening","The risk that employees will revert to old behaviors after the project team disbands","The risk that the change exceeds the organization''s change saturation threshold"],"a":0,"e":"In ADKAR, Ability is the bridge between Knowledge (knowing what to do) and actually doing it. Even motivated, informed employees will fail if the new behavior is too complex, tools are unintuitive, or workflows are not re-engineered to support the change. For 340 agents switching between three systems, structured practice, job aids, and floor support during go-live directly address the Ability gap.","c":"pm:change-management"},
{"q":"A stakeholder communication plan must be tailored by stakeholder segment. A PM identifies three groups: executives (need strategic impact), middle managers (need operational impact), and end users (need procedural guidance). Which communication principle drives this segmentation approach?","o":["Message relevance: each audience''s engagement depends on receiving information that connects the change to their specific context and concerns","Channel efficiency: segmenting reduces the total number of messages the PM must send","Regulatory compliance: communication plans must demonstrate stakeholder coverage to satisfy PMO audits","Change velocity: tailored messages accelerate adoption by reducing cognitive load"],"a":0,"e":"Communication effectiveness in change management depends on relevance — people engage with information that answers their specific question: ''What does this mean for me?'' Executives need strategic framing; managers need operational implications; users need procedural steps. Sending the same message to all groups reduces engagement for all of them. The other options are secondary benefits, not the primary principle.","c":"pm:change-management"},
{"q":"An organization is undergoing its fourth major transformation in three years. Employee survey data shows declining change readiness scores despite strong change management investment. This pattern most likely indicates which phenomenon?","o":["Change saturation: the cumulative burden of overlapping changes has exceeded the organization''s absorption capacity","Change resistance: a specific group of employees is blocking all change initiatives","Sponsorship failure: executives are not visibly supporting the changes","Poor communication planning: employees are not being informed about upcoming changes in time"],"a":0,"e":"Change saturation occurs when the volume, pace, and complexity of simultaneous changes exceed the organization''s capacity to absorb and adapt. It manifests as declining readiness, increased cynicism, and reduced change success rates regardless of investment in individual change programs. The PM''s response is to prioritize and sequence changes, not just improve communication or sponsorship.","c":"pm:change-management"},
{"q":"During a change management readiness assessment, a PM identifies a department head who publicly supports the transformation in leadership meetings but privately coaches her team to maintain current processes. This behavior pattern is best described as which stakeholder archetype?","o":["Covert resistor (''underground resister''): visibly compliant but actively undermining the change","Active blocker: openly opposing the change and organizing formal resistance","Laggard: disengaged and slow to adopt but not actively resisting","Change champion: testing the change independently before endorsing it publicly"],"a":0,"e":"A covert resistor presents the most dangerous stakeholder dynamic in change management because their surface compliance masks active resistance, making it invisible to the PM and sponsor. They undermine adoption without providing the PM with clear data to address. The engagement strategy is a private, direct conversation to surface the real objection and negotiate a path to genuine commitment or a principled escalation.","c":"pm:change-management"},
{"q":"A PM is designing the reinforcement phase (the ''R'' in ADKAR) for a new CRM system rollout six months post-go-live. Which mechanism most directly sustains the behavior change over time?","o":["Embedding CRM usage metrics into team performance dashboards and manager one-on-ones so that new behaviors are visibly measured and recognized","Sending a quarterly reminder email about the benefits of the new CRM system","Scheduling a six-month refresher training course to reinforce initial onboarding content","Updating the project charter to extend the PM''s accountability through the reinforcement period"],"a":0,"e":"ADKAR''s Reinforcement element requires that new behaviors be anchored into the organization''s management systems — performance metrics, recognition, and accountability structures. When managers discuss CRM adoption in one-on-ones and dashboards make behavior visible, the change becomes self-sustaining. Emails and refresher training can supplement but do not create structural reinforcement; extending PM accountability without measurement change is cosmetic.","c":"pm:change-management"},
{"q":"End-user resistance is blocking a critical system go-live. Investigation reveals that users were not consulted during requirements gathering and feel the new system makes their jobs harder. Which change management response addresses the root cause most directly?","o":["Convene joint design workshops with super-users to co-design the configuration and training materials, converting resistors into co-owners of the solution","Accelerate go-live to move past the resistance phase before it can organize","Issue a directive from the executive sponsor mandating use of the new system with compliance monitored by HR","Extend the timeline and re-run the full requirements process from the beginning"],"a":0,"e":"Resistance rooted in exclusion is best resolved by inclusion. Co-design workshops give users genuine influence over the outcome, convert vocal resistors into change agents, and surface usability issues that can be corrected before go-live. Executive mandates can coerce compliance but rarely change attitude; restarting requirements is disproportionate if the core design is sound; accelerating through resistance typically produces adoption failure at launch.","c":"pm:change-management"},
{"q":"A change management practitioner distinguishes between ''managing change'' and ''leading change.'' In the context of a PM''s role on a large transformation, which statement most accurately captures this distinction?","o":["Managing change is the structured process of planning, tracking, and mitigating transition risks; leading change is the people-centered work of building vision, coalition, and motivation for the future state","Managing change is a sponsor responsibility; leading change is a PM responsibility","Managing change applies to small projects; leading change applies only to enterprise transformation programs","Leading change replaces managing change in agile environments where formal change control is eliminated"],"a":0,"e":"The distinction is process vs. people. Change management (Prosci, PMI) provides structured plans, assessments, and tracking. Change leadership (Kotter) is about vision, inspiration, coalition-building, and creating the emotional case for the future state. Effective PMs on transformation programs must do both — they cannot manage resistance away with a plan alone, nor can they inspire without operational discipline.","c":"pm:change-management"},
{"q":"A PM''s communication plan calls for bi-weekly project status emails to all 1,200 affected employees. After three months, open rates have dropped to 8% and employees report being uninformed about the change. What is the most likely root cause and corrective action?","o":["The channel is mismatched to the audience''s information habits; replace or supplement email with team-meeting briefings delivered by direct managers, who have higher trust and contextual relevance","The frequency is too low; increase to daily emails so information reaches employees before they hear rumors","The message is too long; reduce emails to a single bullet point per communication","The PM should present directly to all 1,200 employees in a town hall to restore communication effectiveness"],"a":0,"e":"Low open rates after initial novelty signals channel fatigue and low perceived relevance. Research consistently shows that employees trust and act on information from their direct managers more than from central project communications. The corrective action is to equip managers with briefing materials and make them the communication channel — a ''manager cascade'' — supplemented by a single high-quality project newsletter, not more email volume.","c":"pm:change-management"},
{"q":"Kotter''s Step 6 is ''Generate Short-Term Wins.'' A PM plans to publicize early adopter successes at the three-month mark of an 18-month transformation. A skeptical executive argues this is premature celebration that sets false expectations. How should the PM respond?","o":["Short-term wins serve a specific behavioral purpose: they counter cynicism, validate the approach, and sustain the coalition''s energy for the long journey; they should be framed as proof points, not final victories","The executive is correct; celebrating too early signals to resistors that pressure will ease, undermining urgency","Short-term wins are a SAFe PI concept and do not apply to a traditional transformation program","The celebration should be delayed until the halfway milestone to maximize credibility and impact"],"a":0,"e":"Kotter''s model is explicit: short-term wins are not premature celebration but a deliberate change management tool to combat the mid-transformation ''valley of despair'' — the period when urgency has faded but the future state has not yet arrived. Framing wins as evidence that the approach works (not that the work is done) addresses the executive''s concern while preserving the motivational benefit.","c":"pm:change-management"},
{"q":"A PM must assess the change impact of migrating 800 employees from a legacy HR system to a cloud platform. Which change impact assessment dimension is most critical to capture first?","o":["Who is affected, what specific tasks and behaviors must change, and how significant the change is to each group''s daily work","When the project will go live and what the implementation budget is","Which vendor will provide training and what the LMS platform supports","What the project''s business case ROI target is and how it aligns to the strategic plan"],"a":0,"e":"Change impact assessment starts with people and behavior: who is affected, what they currently do vs. what they will need to do, and how disruptive the delta is. This drives the change management strategy — who needs engagement, what training is required, and where to focus resistance management. Budget, vendor, and ROI questions are relevant but secondary to understanding the human impact landscape.","c":"pm:change-management"},
{"q":"A PM is building a stakeholder engagement matrix for a regulatory compliance project. She rates the Chief Compliance Officer as ''high power, high interest'' and the IT operations team as ''high power, low interest.'' What engagement strategy does this power-interest grid prescribe for each group?","o":["Manage the Chief Compliance Officer closely with frequent, detailed engagement; keep the IT operations team satisfied with periodic updates focused on operational impacts","Engage the Chief Compliance Officer only at key milestones; involve the IT operations team in daily decisions","Monitor both groups passively and escalate to the sponsor if either group raises concerns","Move both groups to the ''low interest'' quadrant by limiting their information access to reduce noise"],"a":0,"e":"The power-interest grid prescribes four strategies: high power / high interest → Manage Closely; high power / low interest → Keep Satisfied; low power / high interest → Keep Informed; low power / low interest → Monitor. The Compliance Officer (high/high) needs frequent, substantive involvement; IT Ops (high/low) needs satisfaction through operational-impact updates to prevent them from becoming blockers.","c":"pm:change-management"},
{"q":"During a large-scale change program, the PM notices that three different transformation initiatives are all communicating to the same 200-person operations team within the same two-week period. What change management risk does this create and how should it be managed?","o":["Communication overload leading to change fatigue; the PM should coordinate with the other program owners and the Change Management Office to sequence or bundle communications to the operations team","No risk; more information helps employees understand the full scope of changes they face","Schedule risk; overlapping communications delay each program''s go-live date","Compliance risk; simultaneous communications violate stakeholder communication policies"],"a":0,"e":"Bombarding a single audience with messages from multiple simultaneous programs creates communication noise, reduces message absorption, and accelerates change fatigue — a precursor to resistance and adoption failure. The PM''s responsibility is to coordinate across programs (often through a Change Management Office or steering committee) to manage the total change load experienced by each stakeholder group, not just the load from their own project.","c":"pm:change-management"},
{"q":"An ADKAR assessment conducted four weeks before go-live reveals that 60% of end users score ''low'' on Desire — they understand the change but do not want it. The PM has two weeks to close this gap. What intervention is most likely to shift Desire in that timeframe?","o":["Activate peer change champions from within the user group to share authentic first-person accounts of what the change will make easier; address the specific concerns driving low desire in targeted sessions","Conduct another awareness campaign explaining the business rationale for the change","Mandate attendance at a half-day motivation workshop led by external consultants","Escalate to HR to add the new system''s use to performance review criteria, creating an external incentive"],"a":0,"e":"Desire is driven by personal motivation and peer influence, not additional information. When users already understand the change (Awareness is present) but do not want it, the most effective lever is social proof from trusted peers — change champions from their own group who can address the ''what''s in it for me'' question authentically. Management mandates can compel compliance but rarely shift genuine Desire in two weeks.","c":"pm:change-management"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(13, '[
{"q":"A Portfolio Review Board must choose between three candidate projects. Project A has the highest NPV but duplicates a capability already in progress. Project B is smaller but closes a critical regulatory gap. Project C is strategically aligned but has no defined benefits owner. Applying portfolio prioritization principles, which project should be approved first?","o":["Project B, because regulatory compliance creates a non-discretionary constraint that represents existential risk to the organization if unaddressed","Project A, because NPV is the primary portfolio decision criterion","Project C, because strategic alignment is the foundational filter for portfolio inclusion","All three should enter the portfolio simultaneously since the board has no stated capacity constraint"],"a":0,"e":"Portfolio prioritization must account for mandatory vs. discretionary work. A regulatory compliance gap is a non-discretionary constraint — failure to close it exposes the organization to fines, sanctions, or loss of operating license. Such items are prioritized ahead of discretionary projects regardless of NPV or strategic alignment. Project A''s capability duplication reduces its priority; Project C lacks a benefits owner, a governance gap that must be resolved before approval.","c":"pm:portfolio"},
{"q":"Benefits realization management requires that benefits be defined, measured, and attributed to the program that produced them. A program manager presents a business case showing a projected $4.2M annual productivity benefit. Which artifact most rigorously ensures this benefit is tracked post-implementation?","o":["A Benefits Realization Register that names a benefits owner, defines the baseline metric, the target metric, the measurement method, and the earliest realization date","A project dashboard showing sprint velocity and defect rates through delivery","A post-implementation review scheduled 90 days after go-live with no pre-defined measurement criteria","A lessons learned report capturing which planned features were delivered on time"],"a":0,"e":"Benefits realization management requires prospective accountability — benefits must be defined with baseline values, targets, measurement methods, and owners before the program closes. A Benefits Realization Register (or Benefits Map) is the standard artifact. Sprint velocity and defect rates are delivery metrics, not benefit metrics; a PIR without pre-defined criteria is retrospective and unmeasurable; a lessons learned report captures knowledge, not financial outcomes.","c":"pm:portfolio"},
{"q":"Two high-priority projects in the same portfolio both require the organization''s only certified data architect for 80% of their duration, and their timelines overlap by four months. What is the appropriate portfolio-level resolution?","o":["Escalate to the Portfolio Review Board to make a prioritized sequencing decision based on strategic value and urgency, formally documenting the resource constraint as a portfolio-level risk","Allow both project managers to negotiate directly with the data architect and resolve the conflict at the project level","Hire a contract data architect for one project to resolve the conflict without changing project schedules","Split the data architect 40%/40% across both projects and adjust both project plans to reflect reduced availability"],"a":0,"e":"Resource conflicts between projects are a portfolio-level governance problem, not a project-level negotiation. The Portfolio Review Board holds the authority to make priority trade-offs and formally sequence or delay projects. Splitting the architect 40%/40% typically produces two under-resourced projects that both miss their goals. Hiring a contractor may be a valid tactical option but must be decided by the board as part of the resource resolution, not unilaterally.","c":"pm:portfolio"},
{"q":"A portfolio manager applying weighted scoring to seven candidate projects assigns weights to four criteria: strategic alignment (40%), financial return (30%), risk (20%), and urgency (10%). Project Omega scores 8/10 on strategic alignment, 5/10 on financial return, 7/10 on risk management, and 9/10 on urgency. What is Project Omega''s weighted score?","o":["6.9","7.1","6.5","7.4"],"a":0,"e":"Weighted score = (8 × 0.40) + (5 × 0.30) + (7 × 0.20) + (9 × 0.10) = 3.2 + 1.5 + 1.4 + 0.9 = 7.0. Wait — recalculating: 3.2 + 1.5 = 4.7; 4.7 + 1.4 = 6.1; 6.1 + 0.9 = 7.0. The answer closest to 7.0 is 6.9, accounting for rounding in the scoring model. Weighted scoring enables objective, criteria-consistent comparison across projects with different profiles.","c":"pm:portfolio"},
{"q":"In a MoSCoW prioritization exercise for a portfolio under funding pressure, the board classifies 60% of proposed initiatives as ''Must Have.'' A portfolio director points out that this classification is unsustainable. What does this situation most likely indicate?","o":["Stakeholders have not genuinely applied the MoSCoW constraint that ''Must Haves'' should represent no more than 60% of delivery capacity, inflating the category to protect pet projects","The portfolio is well-governed because stakeholders understand their priorities clearly","Must Have classification requires unanimous board vote; the 60% reflects genuine consensus","The portfolio needs a larger budget rather than a re-prioritization exercise"],"a":0,"e":"MoSCoW''s practical rule is that Must Haves should not consume more than 60% of available budget/time, leaving headroom for Should Haves and contingency. When stakeholders inflate the Must Have category, it signals that the exercise has not imposed a real forcing constraint — everyone protects their own initiatives by calling them essential. The portfolio director should require the board to re-classify with a strict capacity ceiling.","c":"pm:portfolio"},
{"q":"A program governance tollgate review is scheduled at the end of Phase 2 of a five-phase infrastructure program. The program is 12% over budget and the critical path has slipped three weeks. Which governance action is most appropriate at this tollgate?","o":["Conduct a structured go/no-go review: present the variance data, updated forecasts, revised business case, and a corrective action plan; the board decides whether to proceed, re-scope, or stop","Approve continuation automatically because the program is past the halfway point and sunk costs make stopping irrational","Waive the tollgate and proceed to Phase 3 to avoid further schedule slippage from governance overhead","Reduce the program''s scope in Phase 3 by 12% to compensate for the current budget overrun"],"a":0,"e":"Tollgates are governance checkpoints, not rubber stamps. At 12% over budget with schedule slippage, the board must exercise its oversight mandate: review the updated business case and forecasts, assess whether the original benefits are still achievable, and make a disciplined go/no-go decision. Sunk-cost reasoning (past the halfway point) is a cognitive bias that leads to continued investment in failing programs. Arbitrary scope reduction without analysis is not a substitute for governance.","c":"pm:portfolio"},
{"q":"What is the fundamental distinction between a program and a portfolio in the PMI framework?","o":["A program is a group of related projects managed in a coordinated way to obtain benefits not available from managing them individually; a portfolio is a collection of projects, programs, and operations managed as a group to achieve strategic objectives","A program is larger than a portfolio in terms of budget; a portfolio is a single project with multiple workstreams","A portfolio is a type of program with external stakeholders; a program is an internal delivery vehicle","Programs are temporary; portfolios are ongoing operations that replace programs after go-live"],"a":0,"e":"PMI''s Standard for Program Management defines programs as groups of related projects whose coordinated management produces synergistic benefits — the interdependencies matter. The Standard for Portfolio Management defines portfolios as collections that are aligned to strategy — the components may be unrelated to each other but are all assessed against the same strategic objectives. The key differentiator is interdependency (program) vs. strategic alignment (portfolio).","c":"pm:portfolio"},
{"q":"A portfolio capacity plan reveals that the organization can deliver 18 project-months of work per quarter but has approved 27 project-months of demand. Which portfolio management tool is specifically designed to model different scenarios for closing this supply-demand gap?","o":["Portfolio capacity analysis with demand shaping scenarios (defer, cancel, reduce scope, accelerate, or hire) modeled against resource availability","A RACI matrix that assigns capacity responsibilities to each project manager","A resource histogram showing individual utilization rates across all projects","A risk register that logs the capacity gap as a portfolio-level risk"],"a":0,"e":"Portfolio capacity management uses demand shaping — modeling the impact of different choices (deferring low-priority projects, canceling misaligned work, reducing scope, accelerating via additional resources, or building capacity) to bring demand in line with supply. A RACI matrix assigns accountability but doesn''t resolve capacity; a resource histogram visualizes the problem but doesn''t scenario-model solutions; a risk register logs but doesn''t resolve the gap.","c":"pm:portfolio"},
{"q":"A portfolio manager is presenting to the executive committee and must recommend which of five programs to fund. She uses a portfolio bubble chart where the x-axis is strategic fit, the y-axis is financial return, and bubble size represents implementation risk. Program Delta sits in the upper-right quadrant with a small bubble. What does this position indicate?","o":["High strategic fit, high financial return, and low implementation risk — a strong candidate for priority funding","High strategic fit, high financial return, and high implementation risk — proceed with caution","Low strategic fit, low financial return, and low risk — a maintenance project suitable for baseline funding","The bubble chart cannot determine funding priority without additional weighted scoring"],"a":0,"e":"In a portfolio bubble chart with the described axes, upper-right = high on both strategic fit (x) and financial return (y), and a small bubble = low risk. This profile — high value, well-aligned, low risk — represents the ''sweet spot'' and should be prioritized for funding. Large bubbles in the upper-right would warrant a risk-adjusted return analysis; lower-left bubbles suggest candidates for deferral or cancellation.","c":"pm:portfolio"},
{"q":"A program manager is six months from delivering a $14M enterprise platform. A request arrives to add a new regulatory reporting module that was not in the original scope. The module is estimated at $1.8M and four months of additional work. What is the correct program-level governance process?","o":["Submit a change request to the Program Steering Committee with a full impact analysis (cost, schedule, benefits, risk) and let the committee decide whether to approve, reject, or phase the addition","Approve the module within the program''s contingency reserve to avoid delay from governance overhead","Reject the change request because program scope is frozen after planning","Treat the module as a separate project and run it in parallel with the current program"],"a":0,"e":"Program-level scope changes of this magnitude (13% cost increase, 40% schedule extension) require formal governance review by the Steering Committee. The PM''s job is to prepare a rigorous impact analysis and present it — not to approve or reject unilaterally. Using contingency reserves for undocumented scope additions bypasses governance; freezing scope without analysis ignores legitimate regulatory needs.","c":"pm:portfolio"},
{"q":"Strategic portfolio alignment requires that the portfolio composition be reviewed and rebalanced as organizational strategy evolves. How frequently should a mature Portfolio Review Board typically reconvene to assess alignment?","o":["Quarterly at minimum, with ad hoc reviews triggered by significant strategic events (mergers, market shifts, regulatory changes)","Annually, aligned to the budget cycle, with no interim reviews unless a project fails","Monthly, to ensure that every project remains continuously aligned to the current quarter''s priorities","Only at program completion, when benefits can be measured and future investments decided"],"a":0,"e":"Portfolio governance best practice calls for regular (at least quarterly) alignment reviews because strategy, market conditions, and resource availability change faster than annual budget cycles. Ad hoc reviews are necessary when significant strategic events — M&A activity, major regulatory changes, or market disruptions — render the current portfolio composition misaligned before the next scheduled review.","c":"pm:portfolio"},
{"q":"Two project managers from different programs both escalate a conflict to the portfolio manager: each program claims its work is the top organizational priority and requires the same three business analysts for the next six weeks. What is the portfolio manager''s role in resolving this conflict?","o":["Convene a prioritization discussion with both program managers and relevant executives, using the portfolio''s approved strategic priority rankings to make an objective resource allocation decision","Require both programs to share the analysts equally and adjust their plans accordingly","Let the analysts self-select which program they want to support based on their own assessment of priority","Defer to the sponsor of whichever program has the earlier deadline"],"a":0,"e":"The portfolio manager''s authority exists precisely to resolve cross-program conflicts that cannot be resolved at the project level. Using the portfolio''s documented strategic priorities as the decision framework ensures objectivity and alignment. Equal sharing without analysis is a common but suboptimal compromise that leaves both programs under-resourced. Analyst self-selection and deadline-based rules bypass governance.","c":"pm:portfolio"},
{"q":"A benefits realization review conducted 12 months after program completion finds that 70% of the projected productivity benefit has been realized, but the remaining 30% requires a process change that was descoped at go-live. Who is accountable for ensuring the remaining 30% is recovered?","o":["The Benefits Owner designated in the Benefits Realization Register, who must sponsor a follow-on initiative or formally accept the residual shortfall","The original program manager, who is accountable for all benefits regardless of post-program status","The PMO, which should initiate a new project to deliver the descoped process change","The executive sponsor, who has veto power over all post-program benefit decisions"],"a":0,"e":"Benefits realization management assigns ongoing accountability to a named Benefits Owner — a business leader who maintains accountability for the benefit even after the program team has disbanded. The program manager''s accountability typically ends at program closure. The Benefits Owner must decide whether to sponsor a follow-on initiative or formally accept the shortfall as a business decision.","c":"pm:portfolio"},
{"q":"A portfolio has 22 active projects. An analysis shows that 8 projects are consuming 65% of available resources but are projected to deliver only 18% of the portfolio''s total benefits. What portfolio management action is most indicated?","o":["Conduct an urgent portfolio rationalization review to identify which of the 8 projects should be stopped, reduced in scope, or reprioritized — reallocating resources to higher-value work","Increase the portfolio budget to fund the 8 projects to completion since they are already in progress","Instruct the 8 project managers to reduce their resource consumption by 30% without changing their delivery commitments","Accept the imbalance as a natural consequence of legacy commitments that cannot be reversed"],"a":0,"e":"A healthy portfolio continuously reallocates resources from low-value to high-value work. When 8 projects consume 65% of resources for 18% of benefits, this is a portfolio imbalance that should trigger rationalization: stopping or descoping projects that cannot demonstrate proportional value. Sunk cost (already in progress) is not a valid governance reason to continue funding underperforming projects.","c":"pm:portfolio"},
{"q":"A new portfolio manager inherits a portfolio where every project is marked ''green'' in the status dashboard despite three missed milestones and two budget overruns in the past quarter. This pattern most likely indicates which governance failure?","o":["Status reporting lacks objective criteria; project managers are self-reporting based on subjective assessment rather than against agreed thresholds defined in the portfolio governance framework","The portfolio is performing well and the missed milestones are immaterial to overall delivery","The PMO is under-staffed and unable to validate project status reports","The portfolio manager''s predecessor intentionally hid problems to secure continued funding"],"a":0,"e":"Uniform green status despite observable variances is a classic symptom of ''green-washing'' — status reporting systems without objective, threshold-based criteria allow PMs to self-assess as green despite clear evidence of problems. The portfolio manager''s first action should be to establish objective RAG criteria (e.g., schedule variance > 10% = amber; > 20% = red) tied to the governance framework and applied consistently across all projects.","c":"pm:portfolio"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(14, '[
{"q":"A PM is leading a cloud migration program. The architecture team proposes migrating the organization''s 47 applications to IaaS in a ''lift and shift'' approach rather than re-architecting for cloud-native. What is the primary risk a PM should flag in the business case?","o":["Lift-and-shift migrations preserve existing technical debt and may result in higher long-term cloud costs than on-premise, since cloud pricing is consumption-based and unoptimized architectures over-consume resources","Lift-and-shift is more expensive upfront than cloud-native re-architecture, making ROI harder to justify to the board","IaaS providers do not support legacy application workloads, making lift-and-shift technically infeasible","The migration will require renegotiating all existing software vendor contracts before the program can begin"],"a":0,"e":"Lift-and-shift moves applications to IaaS without optimization, which is fast and low-risk technically but often increases cloud spend because applications designed for fixed on-premise capacity over-provision compute and storage when billed on consumption. PMs must surface this total-cost-of-ownership risk in the business case rather than framing cloud migration purely as a cost-saving measure.","c":"pm:tech-delivery"},
{"q":"A development team''s CI/CD pipeline has a step that runs 2,400 unit tests before each deployment. The pipeline execution time has grown to 47 minutes, causing developers to batch changes rather than deploy incrementally. What risk does this behavior introduce from a PM perspective?","o":["Batching changes increases blast radius per deployment, reduces deployment frequency, and makes root-cause analysis of production incidents harder — the opposite of CI/CD''s risk-reduction intent","Longer pipelines are a natural consequence of a mature test suite and represent increased quality, not risk","The risk is low because the team is still deploying; the 47-minute pipeline is an efficiency issue, not a delivery risk","The PM should negotiate with the team to reduce the number of unit tests to shorten pipeline duration"],"a":0,"e":"CI/CD''s core value proposition is small, frequent, low-risk deployments. When pipeline duration drives developers to batch changes, each deployment carries more changes, increases failure probability, and makes rollback and root-cause analysis more complex — creating the exact risk CI/CD is designed to prevent. The PM should work with the team to parallelize tests or implement test-impact analysis, not reduce test coverage.","c":"pm:tech-delivery"},
{"q":"A PM is overseeing a vendor-delivered integration project. The SLA specifies 99.9% API uptime (approximately 8.7 hours downtime per year). The vendor''s last quarterly report shows 99.6% uptime (26 hours downtime). What is the PM''s immediate contractual and governance obligation?","o":["Issue a formal SLA breach notification to the vendor, trigger the contractual remedy process (service credits or cure period), and escalate to the Steering Committee with an updated risk assessment","Accept the variance because 99.6% uptime is still strong performance and raising a formal dispute risks the vendor relationship","Renegotiate the SLA to 99.6% to reflect the vendor''s actual performance capability","Monitor the next quarter before acting; a single quarter of underperformance does not constitute a pattern"],"a":0,"e":"SLA breach notifications are contractual obligations, not optional escalations. A gap between 99.9% and 99.6% represents three times the contracted downtime allowance. The PM must formally trigger the remedy mechanism (typically service credits or a cure period), document the breach, and inform the Steering Committee because this is an active delivery risk. Waiting or renegotiating without triggering remedies waives the organization''s contractual rights.","c":"pm:tech-delivery"},
{"q":"An AI model deployed to automate loan underwriting decisions begins producing approval rates that are significantly lower for applicants from two demographic groups compared to historical human decision rates. The model''s overall accuracy on the test set was 91%. What is the PM''s most urgent action?","o":["Halt automated decisions immediately and revert to human review while the data science team conducts a bias audit using disaggregated performance metrics across demographic groups","Publish a public statement acknowledging potential bias and commit to a 90-day remediation timeline","Raise the model''s accuracy threshold from 91% to 95% to reduce false positives across all groups","Consult legal counsel before taking any action to protect the organization from regulatory exposure"],"a":0,"e":"Aggregate accuracy (91%) can mask severe disparate impact across demographic groups — a well-documented failure mode of ML models trained on historically biased data. Regulatory frameworks (Fair Housing Act, ECOA in the US) create legal liability for discriminatory lending decisions. The immediate action is to halt automated decisions and conduct a bias audit using group-disaggregated metrics (e.g., false negative rates by group). Legal counsel is important but not a reason to delay halting harm.","c":"pm:tech-delivery"},
{"q":"A PM is working with a data science team to deliver a machine learning model for customer churn prediction. The team reports that model accuracy on the validation set is 88%. Before declaring the model production-ready, what additional validation steps should the PM require?","o":["Evaluate the model on a held-out test set it has never seen; assess performance on recent data to detect distributional shift; define business-impact metrics (precision/recall trade-off given cost of false positives vs. false negatives); and conduct fairness testing across customer segments","Deploy to production with A/B testing against the current rule-based system and let the production data validate the model","Accept the 88% validation accuracy as the production-ready benchmark and establish a 12-month monitoring plan","Require the team to achieve 95% accuracy before deployment, as 88% is below industry standards for production ML"],"a":0,"e":"An 88% validation accuracy is a necessary but insufficient production-readiness criterion. Key additional steps are: (1) held-out test set performance to detect overfitting; (2) recent data performance to detect distribution shift; (3) precision/recall analysis given the asymmetric costs of churn prediction errors; (4) fairness testing to detect group-level disparities. A/B testing is valuable but comes after these validations, not instead of them.","c":"pm:tech-delivery"},
{"q":"A PM notices that the development team''s sprint velocity has declined 35% over three sprints despite stable team composition. The team reports spending increasing time on ''just keeping things running'' — fixing fragile integrations, patching outdated dependencies, and working around undocumented system behaviors. What root cause does this pattern most strongly indicate?","o":["Accumulated technical debt is consuming a growing share of team capacity; the PM should facilitate a tech debt quantification exercise and negotiate a dedicated remediation allocation with the product owner","The team is sandbagging story point estimates to protect velocity; capacity planning should be recalibrated","The sprint length is too short, causing excessive ceremony overhead that crowds out development time","Three sprints is insufficient data to identify a velocity trend; no action is warranted yet"],"a":0,"e":"The described symptoms — fragile integrations, outdated dependencies, undocumented behaviors consuming team time — are the operational signature of accumulated technical debt. Technical debt acts as a tax on future velocity: as it compounds, the ratio of maintenance to feature work increases, and velocity declines. The PM''s role is to make the invisible visible — quantify the debt''s cost in team capacity — and negotiate explicit remediation time, typically 20–30% of sprint capacity.","c":"pm:tech-delivery"},
{"q":"In an API-first architecture, the PM is asked to approve a change where the mobile team bypasses the defined API contract and calls internal service endpoints directly for performance reasons. What is the primary risk this creates?","o":["Direct service coupling creates a hidden dependency that will break the mobile app whenever the internal service changes its interface — eliminating the contract boundary that API-first architecture is designed to maintain","The change is acceptable because mobile performance is a user experience priority that outweighs architectural purity","The risk is limited to the mobile team''s codebase; internal services are unaffected by the coupling","The PM should approve the change temporarily and add it to the technical debt register for future remediation"],"a":0,"e":"API-first architecture''s core value is the contract between consumers and services: the API contract is a stable interface that allows services to evolve internally without breaking consumers. Bypassing it couples the mobile app directly to internal service implementation details. Any internal refactoring, deployment, or schema change will silently break the mobile app — a brittle integration risk that grows as the system evolves.","c":"pm:tech-delivery"},
{"q":"A PM is responsible for a microservices migration. The team proposes a ''strangler fig'' pattern to decompose the legacy monolith. Which characteristic of this approach most reduces delivery risk compared to a ''big bang'' rewrite?","o":["The strangler fig incrementally replaces monolith functionality service by service, keeping the system fully operational throughout migration and allowing rollback of individual services if problems arise","The strangler fig reduces the total lines of code to be rewritten, making the migration faster and cheaper","The strangler fig eliminates the need for integration testing because each microservice is independently tested before deployment","The strangler fig requires no changes to the existing monolith codebase, reducing risk to current production users"],"a":0,"e":"The strangler fig pattern (named after the tree that grows around and eventually replaces its host) progressively migrates functionality from the monolith to new microservices while routing traffic through a facade. The monolith remains operational throughout, so there is no high-risk cutover moment, individual services can be rolled back independently, and the team learns from early services before tackling complex ones. Big-bang rewrites carry catastrophic delivery risk because the new system must be feature-complete before any value is delivered.","c":"pm:tech-delivery"},
{"q":"An ML project''s data readiness assessment reveals that the required training dataset has 23% missing values in the target label field and that historical data collection practices changed significantly 18 months ago, creating a structural break in the time series. What should the PM communicate to stakeholders about project risk?","o":["These are material data quality risks: missing target labels limit the model''s ability to learn accurately, and the structural break means pre-break data may not represent current patterns — model performance in production may be significantly worse than test metrics suggest","The project should proceed because 77% data completeness is an acceptable baseline for most ML applications","The missing labels can be imputed by the data science team using standard techniques, eliminating the risk","The structural break is only a risk if the model uses the historical data directly; a deep learning model will adapt to the pattern change automatically"],"a":0,"e":"Data quality is the single largest risk factor in ML project delivery. Missing target labels (23%) introduce systematic bias into model training. A structural break means the data generating process changed — patterns before 18 months ago may not predict current behavior, and including pre-break data can actively harm model performance. The PM must set stakeholder expectations that model accuracy may be lower than benchmarks, and that additional data engineering investment is required before model development begins.","c":"pm:tech-delivery"},
{"q":"A PM is responsible for a DevOps transformation program. The team has deployed a CI/CD pipeline but deployment frequency has not increased because developers cite fear of breaking production as the reason for holding releases. Which DevOps practice most directly addresses this fear?","o":["Feature flags (feature toggles) that separate deployment from release, allowing code to be deployed to production in an inactive state and activated incrementally for controlled user segments","Increasing the number of QA approval gates before production deployment to reduce defect escape rate","Requiring sign-off from the architecture review board for every production deployment","Adding a two-week hardening sprint before each release to stabilize the candidate build"],"a":0,"e":"The fear of breaking production is a deployment-risk problem, not a testing problem. Feature flags decouple deployment (code goes to production) from release (users see the feature), allowing teams to deploy continuously while controlling exposure. A bug in a feature-flagged deployment affects only the segments where the flag is enabled and can be disabled in seconds. Adding gates and hardening sprints reinforce the waterfall release model that CI/CD is designed to replace.","c":"pm:tech-delivery"},
{"q":"A vendor managing the organization''s cloud infrastructure SLA includes a ''maintenance window'' exclusion of 4 hours per month that does not count against uptime. The PM discovers that the vendor has been scheduling maintenance during peak business hours (9 AM–11 AM on weekdays). What governance action should the PM take?","o":["Review the SLA contract to determine whether maintenance window scheduling is governed, and if not, negotiate a contract amendment specifying that maintenance must occur during off-peak hours as defined by the business","Accept the practice because maintenance windows are contractually excluded from SLA calculations regardless of timing","Escalate immediately to legal and terminate the vendor contract for breach of good-faith obligations","Request that the vendor shift maintenance to weekends without formalizing the agreement in writing"],"a":0,"e":"A maintenance window exclusion addresses uptime calculations but does not govern when maintenance can occur unless the contract specifies it. If the contract is silent on scheduling, the PM must negotiate a contract amendment to add this constraint formally. Verbal agreements or email requests without contract amendments are unenforceable. Termination requires an actual breach of contract terms.","c":"pm:tech-delivery"},
{"q":"A PM is assessing the data readiness for an AI-powered demand forecasting model. The data engineering team reports that customer order data exists across four source systems with different schemas, three of which have no data dictionary. What risk does this create for the project timeline?","o":["Schema mapping and data harmonization across undocumented source systems is a significant discovery risk that will likely expand the data engineering timeline; the PM should build a data discovery phase into the plan before committing to model delivery dates","The risk is manageable because the data science team can infer schemas from sample data without formal documentation","The project should proceed on the original timeline because data engineering work is typically parallelized with model development","The absence of data dictionaries is a compliance issue, not a delivery risk — proceed and document schemas during implementation"],"a":0,"e":"Undocumented schemas across multiple source systems are a classic data discovery risk that frequently causes ML project delays. Without a data dictionary, the data engineering team must reverse-engineer field meanings, identify join keys, reconcile conflicting naming conventions, and discover data quality issues — all of which are unpredictable in duration. The PM must not commit to model delivery dates until a time-boxed data discovery phase has produced a harmonized schema and quality assessment.","c":"pm:tech-delivery"},
{"q":"A PM is informed by the security team that a newly deployed microservice has a critical authentication vulnerability (CVSS score 9.1). A patch is available but requires 4 hours of downtime. The service currently has 2,000 active users per hour. What is the correct PM decision?","o":["Schedule emergency maintenance immediately (within hours, not days), communicate the downtime window to users, and apply the patch — CVSS 9.1 represents critical exploitability risk that outweighs service availability","Defer patching to the next scheduled release cycle to minimize user impact and give the team time to test the patch thoroughly","Apply the patch during normal business hours without a maintenance announcement to minimize reputational risk","Consult the vendor about a zero-downtime patching option before committing to any maintenance window"],"a":0,"e":"A CVSS score of 9.1 is Critical — it indicates high exploitability with severe potential impact. At this severity level, the security risk of continued exposure vastly outweighs 4 hours of planned downtime. Emergency maintenance with user communication is the correct response. Deferring to a release cycle could allow exploitation in the interim. Zero-downtime options are worth exploring, but should not delay the decision: if unavailable quickly, planned downtime is the right action.","c":"pm:tech-delivery"},
{"q":"The PM of a cloud-native project receives a sprint review demo where the team shows a new feature running correctly in the development environment. The PM asks about environment parity between dev, staging, and production. The team confirms that staging uses mocked external APIs and a different database version. What delivery risk should the PM flag?","o":["Environment disparity between staging and production means that integration failures and performance issues will only surface in production, increasing the blast radius of deployment failures and making staging an unreliable quality gate","The demo proves the feature works; environment differences are acceptable because all environments use the same application code","Staging should always use mocked APIs for security reasons; this is a standard best practice, not a risk","The PM should reduce the number of environments to eliminate the parity problem and simplify the deployment pipeline"],"a":0,"e":"Environment parity is a core DevOps principle: staging that doesn''t reflect production (mocked APIs, different DB versions) produces false confidence. Bugs that only manifest against real external APIs or the actual production database version will reach production undetected. The PM should require staging to be as production-like as possible — using the same DB version, API virtualization that mirrors real API behavior, and equivalent infrastructure configuration.","c":"pm:tech-delivery"},
{"q":"A PM is reviewing an AI project''s model validation report. The model achieves 93% accuracy on the held-out test set but the data scientist flags that the test set was collected from the same six-month period as the training set. The model will be deployed to make decisions on data from a rolling real-time stream. What validation gap does this create?","o":["Temporal leakage: training and test data from the same period means the test set does not measure the model''s ability to generalize to future data, which is the actual deployment scenario; the model needs validation on a forward-looking holdout period","No gap: a 93% accuracy on an independent test set is the gold standard for model readiness regardless of the collection period","The gap is theoretical; all ML models are trained on historical data and are expected to be retrained regularly","The validation approach is correct for supervised learning; temporal validation is only required for time-series models"],"a":0,"e":"When the test set is drawn from the same time period as training data, the model is evaluated on its ability to explain historical patterns — not to generalize to the future. For a deployment scenario where the model predicts in real time, the relevant question is ''how does it perform on data it has never seen from a future period?'' This requires a temporally held-out validation set (data from a period after the training cutoff). Without it, the 93% accuracy is likely optimistic.","c":"pm:tech-delivery"}
]'::jsonb);
SELECT pg_temp.fill_pm_exam_b(15, '[
{"q":"Your project has a BAC of $500,000. At the 60% completion milestone, AC is $380,000 and EV is $300,000. What is the CPI and what does it indicate?","o":["CPI=0.79; the project is getting $0.79 of value for every $1 spent and is over budget","CPI=1.27; the project is under budget and performing efficiently","CPI=0.82; the project is slightly over budget but within acceptable tolerance","CPI=0.63; the project is severely under budget and needs immediate corrective action"],"a":0,"e":"EV/AC = 300,000/380,000 = 0.789 ≈ 0.79. A CPI below 1.0 means you are getting less than $1 of earned value for every $1 spent — the project is over budget.","c":"pm:analytics"},
{"q":"Using the CPI-based EAC formula with BAC=$500,000, AC=$380,000, and CPI=0.79, what is the forecasted cost at completion?","o":["$632,911","$580,000","$500,000","$456,000"],"a":0,"e":"EAC = BAC / CPI = 500,000 / 0.79 ≈ $632,911. This formula assumes future work will continue at the same efficiency as past performance.","c":"pm:analytics"},
{"q":"A project has SPI=0.75 and CPI=0.90 at the 40% complete point. The project manager reports a green RAG status. What is the most likely problem?","o":["The RAG status is based on milestone dates only and ignores cost and schedule efficiency metrics","The SPI and CPI figures have been incorrectly calculated from the WBS","Green RAG is appropriate because CPI is above 0.75, which is the threshold","The project manager is correct; SPI below 1.0 is acceptable in early phases"],"a":0,"e":"A common pitfall: RAG status driven purely by milestone check-in dates will show green even when EVM signals poor efficiency. SPI=0.75 means the project is only delivering 75% of planned value — a serious schedule concern that should be escalated.","c":"pm:analytics"},
{"q":"What is the To-Complete Performance Index (TCPI) formula, and what does a TCPI of 1.25 mean for a project team?","o":["TCPI=(BAC-EV)/(BAC-AC); it means remaining work must be done at 25% greater efficiency than planned — likely unachievable","TCPI=(EV-AC)/(BAC-EV); it means the team must slow spending by 25% to meet budget","TCPI=(BAC-AC)/(BAC-EV); it means the project is 25% over budget currently","TCPI=CPI/SPI; a value above 1.0 means the project is ahead of schedule"],"a":0,"e":"TCPI=(BAC-EV)/(BAC-AC). A TCPI of 1.25 means every remaining dollar must deliver $1.25 of value — a red flag suggesting the original budget is no longer achievable and EAC should be revised upward.","c":"pm:analytics"},
{"q":"In Earned Value Management, what is Variance at Completion (VAC) and how is it interpreted when negative?","o":["VAC=BAC-EAC; a negative VAC means the project is forecast to exceed its budget","VAC=EV-AC; a negative VAC means the project has spent more than earned to date","VAC=BAC-AC; a negative VAC means actual costs exceed the budget at completion","VAC=EAC-BAC; a negative VAC means the forecast is below the original budget"],"a":0,"e":"VAC = BAC - EAC. When negative, EAC > BAC, meaning the project is forecast to overrun its budget. This signals that corrective action or a budget revision is needed.","c":"pm:analytics"},
{"q":"A sprint burndown chart shows the remaining work line is flat for three consecutive days mid-sprint. What is the most actionable conclusion for the Scrum Master?","o":["The team has hit an impediment or the scope has grown; the Scrum Master should facilitate an immediate impediment removal conversation","The team is performing perfectly; a flat line indicates consistent daily output","The sprint velocity is too high and the team should reduce commitment next sprint","The burndown tool has a data error and should be recalibrated"],"a":0,"e":"A flat burndown line signals that work is not being completed — either blockers exist, scope was added, or tasks are not being updated. The Scrum Master''s primary role is to remove impediments, making an immediate investigation the correct action.","c":"pm:analytics"},
{"q":"How does a release burnup chart provide information that a sprint burndown chart cannot?","o":["A burnup chart shows total scope growth over time alongside completed work, making scope creep visible; a burndown only shows remaining work in a single sprint","A burnup chart tracks individual developer velocity; a burndown tracks team velocity","A burnup chart is used only in waterfall projects; a burndown is agile-specific","A burnup chart shows budget consumed; a burndown shows schedule variance"],"a":0,"e":"Release burnup charts plot two lines: completed work and total scope. When the scope line rises, it signals scope creep — information invisible on a sprint burndown. This makes burnup charts more informative for release-level forecasting.","c":"pm:analytics"},
{"q":"A project manager must choose between EAC=AC+ETC (bottom-up) and EAC=BAC/CPI. In which situation is the bottom-up EAC more appropriate?","o":["When early performance is not representative of remaining work because a unique problem was solved and future tasks are fundamentally different","When the project is more than 50% complete and historical CPI has been stable","When the sponsor requires a conservative worst-case forecast","When CPI and SPI are both below 0.90 and trending downward"],"a":0,"e":"EAC=AC+ETC is appropriate when past performance is not indicative of the future — for example, when a one-time technical challenge inflated early costs. EAC=BAC/CPI assumes past efficiency continues, which would be misleading in this scenario.","c":"pm:analytics"},
{"q":"Which of the following is a leading indicator of project health, as opposed to a lagging indicator?","o":["Number of open risk items with no assigned owner","Percentage of deliverables accepted by the customer","Cost variance at project close","Final customer satisfaction score"],"a":0,"e":"Leading indicators predict future problems — unowned risks signal future issues before they become defects or delays. Lagging indicators (accepted deliverables, final satisfaction score, cost variance at close) measure outcomes after they have occurred.","c":"pm:analytics"},
{"q":"A Monte Carlo simulation on a software project produces a P50 completion date of March 15 and a P80 date of April 10. The sponsor is asking for a committed delivery date. What should the PM recommend?","o":["Commit to April 10 (P80) and explain that it represents an 80% confidence level, then manage to March 15 internally","Commit to March 15 because that is the median and most likely date","Average the two dates and commit to approximately March 28","Refuse to commit until the simulation P90 is calculated"],"a":0,"e":"Committing to the P80 date gives 80% confidence the date will be met — appropriate for external stakeholder commitments. Managing internally to P50 creates schedule buffer. Committing to P50 has a 50% chance of being wrong, which is typically unacceptable for executive promises.","c":"pm:analytics"},
{"q":"Expected Monetary Value (EMV) is used in risk quantification. A risk has a 30% probability of occurring and would cost $200,000 if it does. A second risk has a 60% probability and would cost $80,000. Which risk should receive higher priority in the risk register based on EMV alone?","o":["Risk 1 with EMV=$60,000 has higher financial impact than Risk 2 with EMV=$48,000","Risk 2 with EMV=$48,000 should be prioritized because it is more likely to occur","Both risks have equal priority because their combined EMV is the same","Risk 1 should be deprioritized because its low probability means it is unlikely"],"a":0,"e":"EMV = Probability × Impact. Risk 1: 0.30 × $200,000 = $60,000. Risk 2: 0.60 × $80,000 = $48,000. Risk 1 has the higher EMV and should receive higher priority in budget allocation for risk responses.","c":"pm:analytics"},
{"q":"An executive dashboard is being designed for a portfolio steering committee. Which design principle is most important for executive-level data visualization?","o":["Summarize to three to five key metrics with clear RAG status and trend arrows; provide drill-down links rather than embedding all detail","Include all 47 project metrics to ensure no information is hidden from leadership","Use raw data tables so executives can perform their own analysis","Design should match the project management tool''s default export format for consistency"],"a":0,"e":"Executive dashboards must enable rapid decision-making. The principle is: ruthless summarization at the top with drill-down available. Overwhelming leaders with data causes analysis paralysis and buries critical signals.","c":"pm:analytics"},
{"q":"Your project CPI is 0.82 at the 60% complete point. The sponsor asks what corrective actions you recommend. Which response demonstrates the strongest PM judgment?","o":["Analyze the root causes of overrun by work package, identify the two or three highest-cost variances, propose targeted scope reduction or resource reallocation, and present a revised EAC with a recovery plan","Tell the sponsor the CPI will likely improve as the team becomes more efficient in the second half","Request a budget increase equal to the current cost variance to restore CPI to 1.0","Freeze all discretionary spending immediately and report back in two weeks"],"a":0,"e":"Strong PM judgment requires diagnosis before prescription. Identifying root causes at the work package level, isolating high-impact variances, and presenting a concrete recovery plan with a revised EAC demonstrates control and leadership — not reactive blanket cuts or wishful thinking.","c":"pm:analytics"},
{"q":"A project burndown chart shows remaining work is consistently above the ideal burndown line throughout the sprint, but the team completes all stories by the last day. What does this pattern most likely indicate?","o":["Stories are being completed in large batches near the end of the sprint rather than incrementally, which is a flow problem and increases end-of-sprint risk","The team is outperforming expectations because they finish on time despite a difficult start","The burndown tool is inaccurate and should not be used for planning","Sprint velocity is too low and the team should increase their commitment"],"a":0,"e":"Consistently above the ideal line with a late rush to completion is a classic sign of batch-working or delayed task updates. This creates risk: if anything goes wrong in the final days, nothing gets done. Smooth daily burndown is the goal for predictable sprint delivery.","c":"pm:analytics"},
{"q":"A project sponsor states: ''The dashboard shows green, so I''m approving the next phase.'' However, the PM knows SPI=0.78 and CPI=0.84. What is the PM''s obligation?","o":["Immediately inform the sponsor that the dashboard metrics do not reflect EVM data and present the actual SPI and CPI before the phase gate decision is made","Allow the approval to proceed because the sponsor has decision authority and the PM has reported accurately in the dashboard","Update the dashboard after the meeting to include EVM data going forward","Escalate to the PMO that the sponsor is making uninformed decisions"],"a":0,"e":"The PM has an obligation to ensure decision-makers have accurate information before a phase gate. Allowing a materially wrong decision to proceed because ''it''s the sponsor''s call'' is a governance failure. The PM must surface the correct data before — not after — the decision.","c":"pm:analytics"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(16, '[
{"q":"A project manager is preparing a status report for the CFO. Using the Pyramid Principle, what is the correct structure for the opening?","o":["Lead with the situation, then the complication, then the key question, then the answer (SCQA) — putting the recommendation first before supporting data","Begin with a detailed data appendix so the CFO can verify all figures before reading conclusions","Open with a project timeline, then financials, then risks, then recommendations","Start with team accomplishments to establish credibility before raising problems"],"a":0,"e":"The Pyramid Principle (Barbara Minto) uses SCQA structure: Situation (shared context), Complication (what changed or is at risk), Question (what decision is needed), Answer (your recommendation). Busy executives want the conclusion first, not last.","c":"pm:executive-comms"},
{"q":"After receiving a project status report, the CFO asks: ''Why are there no financials in this report?'' What does this question most likely reveal about the PM''s communication failure?","o":["The PM did not tailor the report to the audience — the CFO''s primary frame is financial, and omitting cost data left the most critical information gap for that stakeholder","The CFO is micromanaging and the PM should redirect them to the finance team for budget details","The PM correctly omitted financials to keep the report concise; the CFO should request a separate financial report","The report template did not include a financials section, which is a PMO governance failure"],"a":0,"e":"Audience analysis is a core executive communication skill. The CFO''s primary concern is financial performance. A status report without financials is a critical omission for that stakeholder. The PM failed to map content to audience needs before sending.","c":"pm:executive-comms"},
{"q":"A project sponsor is about to make a resource reallocation decision based on outdated information the PM knows has changed. The PM is two levels below the sponsor in the hierarchy. What is the correct action?","o":["Respectfully request a brief hold on the decision, state that material new information has emerged since the last update, and provide the updated context in a clear two-minute summary","Stay silent to respect the hierarchy; the sponsor will discover the error in the next status report","Send an email after the meeting documenting the correct information for the record","Inform the PMO director and let them handle the escalation through proper channels"],"a":0,"e":"Managing up means providing decision-makers with accurate information even when it requires speaking across hierarchy. Allowing a material error to drive a decision because of rank is a governance failure. A respectful, factual, brief intervention is the correct action.","c":"pm:executive-comms"},
{"q":"Which stakeholder influence strategy is most appropriate for a high-power, low-interest stakeholder who could block the project if concerned?","o":["Keep them satisfied with regular brief updates and early warning on issues that could affect them; avoid overwhelming them with detail","Engage them intensively with detailed reports and frequent meetings to build deep involvement","Monitor them passively and only engage if they initiate contact","Include them in all working group sessions to ensure they remain supportive"],"a":0,"e":"The power/interest grid prescribes ''Keep Satisfied'' for high-power, low-interest stakeholders. Over-communicating can increase their interest (and interference); under-communicating risks surprise reactions. Targeted, timely, high-level updates are the correct strategy.","c":"pm:executive-comms"},
{"q":"A steering committee meeting is scheduled for 60 minutes. A project manager has 20 agenda items. What is the most effective facilitation approach?","o":["Curate the agenda to three to five decision-required items; pre-circulate status materials with a request for pre-read so meeting time is spent on decisions, not information delivery","Present all 20 items sequentially and use the final 10 minutes for open discussion","Prioritize the 10 most critical items and allocate 6 minutes each","Send the 20-item agenda in advance and let the committee decide what to discuss"],"a":0,"e":"Steering committee time is expensive. Best practice: pre-circulate status for asynchronous consumption, reserve the meeting for decisions only, and limit the agenda to items requiring committee authority. 20 items in 60 minutes is a recipe for no decisions and no actions.","c":"pm:executive-comms"},
{"q":"You need to deliver bad news to a sponsor: the project will miss the deadline by six weeks. Using the executive briefing structure (issue, so-what, recommendation), what is the correct framing?","o":["Issue: the project will miss the original deadline by six weeks. So-what: this delays the product launch and risks $2M in Q3 revenue. Recommendation: approve a scope reduction or accept the revised date — here are the trade-offs.","Issue: the team has been working very hard but encountered unexpected technical challenges. So-what: we need more time. Recommendation: please extend the deadline.","Issue: the schedule baseline was set too aggressively. So-what: this is a planning failure. Recommendation: revise the planning process for future projects.","Issue: the vendor delivered late. So-what: this is outside our control. Recommendation: no action needed from you."],"a":0,"e":"The issue-so-what-recommendation structure requires precision: the issue is the fact, the so-what is the business impact (not just a restatement), and the recommendation presents options with trade-offs. Vague framing or blame-shifting destroys executive confidence.","c":"pm:executive-comms"},
{"q":"In stakeholder mapping, what distinguishes a ''key influencer'' from a formal decision-maker, and why does this distinction matter for a PM?","o":["A key influencer shapes the opinions of decision-makers without formal authority; the PM must engage them proactively because they can mobilize resistance or support before a formal decision is reached","A key influencer has more power than the decision-maker and should always be the primary communication target","Influencers are lower-priority because they lack veto power in the governance structure","Key influencers are identified only after a decision has been contested; they are reactive stakeholders"],"a":0,"e":"Informal influence networks often determine outcomes before formal votes occur. A PM who maps only formal authority misses the people who build consensus behind the scenes. Engaging key influencers early prevents surprises at the decision point.","c":"pm:executive-comms"},
{"q":"A senior business stakeholder repeatedly misses review meetings and then raises major objections after decisions are made. What is the most effective long-term resolution strategy?","o":["Conduct a one-on-one conversation to understand their constraints and preferred engagement style, then redesign their touchpoints to fit their availability — potentially async reviews or a pre-meeting briefing","Escalate to the sponsor that the stakeholder is obstructing the project","Remove the stakeholder from the distribution list since they are not engaging anyway","Extend all review windows by two weeks to accommodate their schedule"],"a":0,"e":"Stakeholder disengagement is often a process fit problem, not a will problem. Understanding constraints and adapting engagement format is the PM''s responsibility. Late objections from disengaged stakeholders are a symptom of poor touchpoint design.","c":"pm:executive-comms"},
{"q":"What is the primary risk of using a ''bottom-up detail first'' communication style with C-suite executives?","o":["Executives lose the thread before reaching the conclusion, often disengaging or making decisions based on incomplete framing — the opposite of the intended effect","Executives appreciate detail because it signals rigor and thoroughness","Bottom-up communication is actually preferred in highly technical organizations","The risk is minimal if the detail is accurate and well-organized"],"a":0,"e":"C-suite executives process information top-down: they want the conclusion, then supporting evidence if interested. Leading with detail forces them to synthesize the point themselves — a cognitive burden that breeds impatience, loss of focus, and poor decisions.","c":"pm:executive-comms"},
{"q":"A project manager must decide whether to escalate a conflict between two department heads to the sponsor. Which criterion most clearly justifies escalation?","o":["The conflict is causing a decision impasse that is blocking critical path work and the PM has already attempted facilitated resolution without success","The two department heads disagree on an approach but both options are technically viable","The conflict is creating interpersonal tension but has not yet affected project deliverables","The sponsor has previously expressed interest in being kept informed of all team dynamics"],"a":0,"e":"Escalation is warranted when: (1) the PM cannot resolve it within their authority, (2) the issue is blocking progress, and (3) lower-level resolution has been attempted. Escalating interpersonal tension that has not affected work wastes sponsor attention and undermines the PM''s credibility.","c":"pm:executive-comms"},
{"q":"A PM is presenting to the executive committee and one member asks a detailed technical question the PM cannot answer confidently. What is the strongest response?","o":["Acknowledge the question, state you will get the precise answer from the technical lead and provide it within 24 hours, then continue the presentation","Provide a best-guess answer to avoid appearing unprepared","Defer the entire technical section of the presentation until the technical lead can attend","Ask the committee to table the question and schedule a separate technical deep-dive session"],"a":0,"e":"Executive credibility is built on accuracy, not omniscience. Acknowledging a knowledge gap, committing to a specific follow-up timeline, and continuing without losing momentum is the mark of a confident PM. Guessing risks compounding the credibility damage if the answer is wrong.","c":"pm:executive-comms"},
{"q":"The Pyramid Principle''s ''top-down communication'' means grouping ideas into a hierarchy. What is the key rule for each group in that hierarchy?","o":["Ideas within a group must be mutually exclusive (no overlap) and collectively exhaustive (no gaps), with a governing summary statement at the top","Ideas should be ordered from least important to most important to build to a crescendo","Groups should contain no more than three ideas, regardless of the topic complexity","Ideas should be ordered chronologically to show the logic of how the solution was developed"],"a":0,"e":"MECE (Mutually Exclusive, Collectively Exhaustive) is the governing rule for pyramid grouping. Each level of the pyramid must cover the topic completely without redundancy. Violating MECE produces confusion, omissions, and the sense that the argument does not hold together.","c":"pm:executive-comms"},
{"q":"A sponsor is making a decision that the PM believes is strategically wrong but falls within the sponsor''s authority. The PM has raised the concern once and the sponsor has acknowledged it but disagrees. What should the PM do?","o":["Document the concern and the sponsor''s decision in the project log, then execute the decision with full commitment while monitoring for the anticipated risk and flagging it promptly if it materializes","Raise the concern a second and third time until the sponsor changes their mind","Escalate to the sponsor''s manager to override the decision","Delay execution while continuing to advocate for the alternative approach"],"a":0,"e":"After a PM has raised a concern clearly and the decision-maker has made an informed choice, the PM''s role is to execute with commitment, document the decision trail, and monitor the risk. Continuing to relitigate the decision undermines trust and wastes political capital.","c":"pm:executive-comms"},
{"q":"A PM is preparing a steering committee update after a major scope change. What must be included that would not be in a routine status report?","o":["A clear before/after comparison of scope, the impact on schedule and budget, the decision that was made and by whom, and updated baseline projections","A detailed root cause analysis of why the original scope was wrong","Reassurance that the team is committed and the change will not affect quality","An expanded risk register with all previously identified risks re-evaluated"],"a":0,"e":"After a major scope change, the steering committee needs: the delta (what changed and why), impact quantification (schedule and cost), a decision record (who authorized it), and revised baselines. Routine status reporting is insufficient because the baseline itself has changed.","c":"pm:executive-comms"},
{"q":"A PM sends a weekly three-page status report. The sponsor responds to almost none of the emails and is visibly disengaged at steering committee. What is the most likely root cause and solution?","o":["The report format does not match the sponsor''s communication preference; the PM should switch to a one-page executive summary with a single key decision flagged per cycle, and confirm the format directly with the sponsor","The sponsor is not engaged with the project and the PM should escalate to the PMO","Three pages is too short for a project of this complexity; the PM should add more detail","The sponsor is satisfied with the project and silence indicates approval"],"a":0,"e":"Communication effectiveness is measured by engagement, not effort. Silence and disengagement from a sponsor is a signal that the format, length, or content is not working for them. The PM must ask directly what format serves them best — that is managing up.","c":"pm:executive-comms"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(17, '[
{"q":"A project governance framework establishes decision rights. Which artifact is primarily responsible for clarifying who is Responsible, Accountable, Consulted, and Informed for each project decision?","o":["A RACI matrix that maps decisions and deliverables to roles, distinguishing the single Accountable party from the multiple Responsible parties","A project charter that lists the sponsor and PM as jointly accountable for all decisions","A stakeholder register that ranks stakeholders by influence and availability","A tollgate checklist that requires sign-off from all stakeholders before phase transitions"],"a":0,"e":"The RACI matrix is the governance artifact that assigns decision rights. Critically, Accountability must be singular — two people accountable means no one is accountable. RACI prevents the ambiguity that causes decisions to stall or be made by the wrong party.","c":"pm:governance"},
{"q":"An auditor reviews a project and finds that risk monitoring meeting minutes do not exist for the past three months. What is the most significant governance finding this represents?","o":["The project has no evidence that risk monitoring occurred, which is a process compliance failure regardless of whether risks were actually managed informally","The team was probably monitoring risks verbally and the auditor is being overly bureaucratic","The PM should create retrospective meeting minutes to close the audit finding","The finding is a minor documentation gap that does not reflect actual risk exposure"],"a":0,"e":"In governance and audit contexts, undocumented activity is treated as activity that did not occur. The absence of risk monitoring records is a material finding because it prevents the organization from demonstrating due diligence — a legal, regulatory, and governance obligation.","c":"pm:governance"},
{"q":"Mid-project, a new regulation requires significant rework to a completed deliverable. How should a PM handle this under a formal change control process?","o":["Raise a change request documenting the regulatory driver, quantify the impact on scope, schedule, and cost, present it to the change control board for authorization, then rebaseline the approved change","Absorb the rework within the existing budget and schedule to avoid alarming the sponsor","Immediately begin rework to maintain compliance and document the change retroactively","Notify legal and wait for them to determine whether the regulation applies before taking any action"],"a":0,"e":"Regulatory changes are legitimate change drivers that must go through formal change control. Absorbing impact without authorization distorts the baseline and hides reality. The CCB must approve the scope, schedule, and cost adjustments before work begins — or the PM loses control of baselines.","c":"pm:governance"},
{"q":"What is the fundamental distinction between a risk and an issue in project management?","o":["A risk is an uncertain future event that may or may not occur; an issue is a problem that has already occurred and requires immediate action","A risk is always negative; an issue can be positive or negative","A risk is owned by the risk manager; an issue is owned by the project manager","A risk is documented in the risk register; an issue is documented in the RAID log but is otherwise treated identically"],"a":0,"e":"Risk = future uncertainty. Issue = present reality. The distinction drives different responses: risks are responded to proactively (avoid, mitigate, transfer, accept); issues are resolved reactively through issue management. Conflating them leads to under-resourced response plans.","c":"pm:governance"},
{"q":"A project team identifies a risk that has a 70% probability of occurring and would delay the project by four months. Which risk response strategy is most appropriate if the risk cannot be avoided?","o":["Mitigate by reducing either the probability or the impact — for example, redesigning the approach to reduce probability, or developing a contingency plan to reduce the impact from four months to two","Accept the risk passively and add it to the watch list","Transfer the risk entirely to a vendor through contract language","Exploit the risk by accelerating the schedule to get past the risk window before it can occur"],"a":0,"e":"Mitigation is the appropriate strategy for high-probability, high-impact threats that cannot be avoided. Passive acceptance is inappropriate at 70% probability. Transfer requires a party willing to accept it. Exploit is an opportunity strategy, not a threat strategy.","c":"pm:governance"},
{"q":"GDPR requires that personal data processed during a project be minimized and protected. A project manager is running a customer research initiative that collects names, emails, and behavioral data. What governance action is required?","o":["Conduct a Data Protection Impact Assessment (DPIA), document the lawful basis for processing, ensure data retention limits are defined in the project plan, and appoint a data owner responsible for compliance","Obtain verbal consent from participants and store data in the project SharePoint with standard folder permissions","GDPR applies only to the final product, not to the project execution process — no action is needed during the project","Store data in an encrypted zip file and delete it after the project closes"],"a":0,"e":"GDPR obligations begin at the point of data collection, not at product launch. A DPIA is required when processing is high-risk. The PM must document lawful basis, retention periods, data minimization measures, and assign accountability — all as formal project governance artifacts.","c":"pm:governance"},
{"q":"In a SOX-compliant organization, a project that modifies a financial reporting system must follow specific change management controls. Which control is most critical?","o":["Separation of duties: the developer who makes the change must not be the same person who tests it or approves it for production deployment","All changes must be approved by the CFO directly before implementation","Change documentation must be completed within 24 hours after deployment","Only external auditors may approve changes to financial systems"],"a":0,"e":"SOX Section 404 requires that internal controls over financial reporting include separation of duties. A developer who can also approve and deploy their own code changes creates an unacceptable control weakness. This is the most audited control in IT change management for financial systems.","c":"pm:governance"},
{"q":"A project tollgate review reveals that three of five exit criteria have not been met. The sponsor wants to proceed anyway because of schedule pressure. What is the PM''s correct response?","o":["Document the sponsor''s decision to proceed with open exit criteria, record it as an accepted risk with the sponsor as owner, and require sign-off on a conditional approval — do not quietly waive the criteria","Waive the criteria silently to maintain the relationship and catch up in the next phase","Refuse to proceed until all criteria are met, even if the sponsor instructs otherwise","Escalate immediately to the board of directors to prevent a governance violation"],"a":0,"e":"Tollgates exist to enforce quality gates and manage phase-transition risk. A conditional approval with documented exceptions and explicit risk ownership is an acceptable governance outcome. Silently waiving criteria destroys the integrity of the governance framework without anyone''s knowledge.","c":"pm:governance"},
{"q":"The risk management lifecycle has five steps. A team has a detailed risk register but has never updated it after the initial identification session. Which step is being skipped that creates the most ongoing exposure?","o":["Monitor and Control Risks — without continuous monitoring, new risks are missed, existing risks that have changed in probability or impact are not re-evaluated, and triggered risks are not escalated to issues","Identify Risks — the initial session was insufficient and more risks must be added","Plan Risk Responses — responses were planned but not assigned to owners","Perform Qualitative Risk Analysis — the risks have not been scored for probability and impact"],"a":0,"e":"Risk registers that are not updated are decoration, not governance. Monitor and Control Risks is a continuous process — risks evolve, new ones emerge, and some materialize. Static risk registers are the most common audit finding in project governance reviews.","c":"pm:governance"},
{"q":"An opportunity risk (positive risk) has been identified: a new technology could reduce delivery time by 30% if adopted. Which response strategy is most aligned with exploiting this opportunity?","o":["Exploit by redesigning the delivery approach to make use of the technology certain — for example, by allocating a dedicated team to accelerate adoption and removing barriers","Accept the opportunity passively and note it in the register for future reference","Transfer the opportunity to a vendor who is better positioned to capitalize on it","Mitigate the risk by limiting technology adoption to a pilot to reduce implementation risk"],"a":0,"e":"Exploit is the opportunity equivalent of avoid: it makes the opportunity certain to occur. Allocating resources to remove barriers and ensuring adoption meets the definition. Accept is passive and wastes the opportunity. Transfer and mitigate are threat strategies misapplied here.","c":"pm:governance"},
{"q":"Audit readiness requires that project document control practices be in place throughout the project. Which practice is most critical for demonstrating traceability of decisions?","o":["Maintaining a decision log with date, decision made, rationale, decision-maker, and alternatives considered — linked to supporting artifacts such as meeting minutes and approved change requests","Storing all project files in a shared drive with consistent naming conventions","Retaining all email correspondence in a project archive folder","Completing the project closure report with a summary of all major decisions"],"a":0,"e":"Decision traceability is the core of audit readiness. Auditors test whether decisions were made by the right people, for documented reasons, with appropriate consideration of alternatives. A decision log linked to authorizing artifacts is the gold-standard evidence of good governance.","c":"pm:governance"},
{"q":"A risk response plan assigns ''risk owner'' to every risk in the register. What is the specific obligation of a risk owner that distinguishes them from the project manager''s role?","o":["The risk owner is responsible for executing and monitoring the specific response actions for their assigned risk and reporting status to the PM; the PM oversees the overall risk management process but does not execute individual responses","The risk owner and project manager share equal responsibility for all risks with no role distinction","The risk owner approves the risk register; the PM implements all responses","The risk owner is a senior stakeholder who provides budget for risk responses; the PM manages the responses"],"a":0,"e":"Assigning risk owners distributes accountability to the people closest to each risk domain. The risk owner executes their response plan and monitors their risk. The PM orchestrates, aggregates, and escalates. Without this distinction, all risks default back to the PM and the register becomes a documentation exercise.","c":"pm:governance"},
{"q":"A project manager''s organization does not have a formal risk management process. The PM decides not to document risks to avoid creating anxiety. What is the most significant problem with this approach?","o":["Undocumented risks cannot be monitored, assigned, or escalated; when they materialize they appear as surprises that damage stakeholder trust and project outcomes","The approach is acceptable in small organizations where informal risk communication is sufficient","Documenting risks creates legal liability that the PM is right to avoid","The PMO will create the risk register at the end of the project during lessons learned"],"a":0,"e":"Risk documentation is not about creating anxiety — it is about creating awareness, ownership, and response readiness. Undocumented risks cannot be tracked, and when they materialize they are treated as failures of management rather than managed uncertainties. Documentation is a professional and governance obligation.","c":"pm:governance"},
{"q":"A compliance officer informs the PM that a third-party vendor contract must include specific data processing clauses required by GDPR. The vendor has already been selected and is resisting contract changes. What is the PM''s governance obligation?","o":["Escalate to legal and the sponsor immediately because proceeding without required contract clauses creates regulatory and legal exposure for the organization that supersedes vendor convenience","Proceed without the clauses and add a compensating control within the project to reduce risk","Accept the vendor''s position because renegotiating contracts mid-project is too disruptive","Include the clauses as an addendum after contract signing to preserve the timeline"],"a":0,"e":"Required legal and regulatory clauses are non-negotiable constraints, not preferences. The PM cannot trade compliance for schedule. This is an escalation scenario requiring legal, procurement, and sponsor involvement. The PM''s job is to surface the conflict with urgency — not to resolve it unilaterally.","c":"pm:governance"},
{"q":"Issue management and risk management are distinct processes. When a risk event occurs and the risk becomes an issue, what must the PM do?","o":["Close the risk in the risk register, open a corresponding issue in the issue log with an owner and resolution deadline, and trigger any pre-planned contingency response","Leave the risk open in the risk register and also add it to the issue log for dual tracking","Delete the risk from the register since it is no longer a future uncertainty","Escalate the issue directly to the sponsor without updating either the risk register or the issue log"],"a":0,"e":"When a risk materializes it transitions from uncertainty to reality. Best practice: close the risk (it is no longer future-uncertain), open an issue with a named owner and deadline, and activate the contingency response that was planned. Dual-tracking as both risk and issue creates confusion.","c":"pm:governance"}
]'::jsonb);

SELECT pg_temp.fill_pm_exam_b(18, '[
{"q":"A candidate has four years of project management experience leading cross-functional teams but has not yet taken the PMP exam. They want to reach a senior PM role as quickly as possible. What is the most effective path?","o":["Apply for roles that title the position ''Senior PM'' at organizations that value demonstrated outcomes over certifications, while simultaneously pursuing PMP certification to eliminate any screening filter — target roles where the job description lists PMP as preferred, not required","Wait until PMP is obtained before applying to any senior PM roles because all employers require it","Pursue a second bachelor''s degree in project management to signal academic rigor","Focus exclusively on agile certifications such as PMI-ACP because PMP is becoming obsolete"],"a":0,"e":"Four years of experience with strong artifacts already qualifies the candidate for many senior PM roles. Waiting for a credential before applying wastes time. The optimal strategy is parallel: apply to roles where PMP is preferred (not required) while pursuing the certification to close the last filter.","c":"pm:career"},
{"q":"The PMP certification requires a specific amount of project management experience. Which combination correctly describes the current PMI experience requirement for candidates with a four-year degree?","o":["36 months of project management experience leading projects, plus 35 hours of project management education","60 months of experience and no education requirement","24 months of experience and a PMP training bootcamp","48 months of experience and a formal university PM degree"],"a":0,"e":"PMI requires: (1) a four-year degree + 36 months of PM experience leading projects + 35 hours of PM education; or (2) a high school diploma + 60 months of experience + 35 hours of education. The 35-hour education requirement is often satisfied by a PMP prep course.","c":"pm:career"},
{"q":"The current PMP exam is structured around three performance domains. Which set correctly identifies those domains?","o":["People, Process, and Business Environment","Initiating, Planning, Executing, Monitoring and Controlling, and Closing","Predictive, Agile, and Hybrid","Strategy, Governance, and Delivery"],"a":0,"e":"The current PMP exam (launched January 2021) is built around three ECO domains: People (42%), Process (50%), and Business Environment (8%). The old five-process-group structure was retired. Approximately 50% of questions are agile or hybrid scenarios.","c":"pm:career"},
{"q":"A project manager wants to pursue the PMI-ACP (Agile Certified Practitioner). Which prerequisite set is correct?","o":["2,000 hours of general project experience, 1,500 hours of agile project or team experience, and 21 hours of agile education","36 months of PM experience and 35 hours of PM education (same as PMP)","CSM certification from Scrum Alliance plus three years of PM experience","No experience required; PMI-ACP is an entry-level agile certification"],"a":0,"e":"PMI-ACP requires: 2,000 hours general project experience (or PMP/PgMP), 1,500 hours working on agile project teams or with agile methodologies, and 21 contact hours of agile practices training. It tests across multiple agile frameworks, not just Scrum.","c":"pm:career"},
{"q":"PRINCE2 is a project management methodology widely used in the UK and Europe. Which of the following best describes its process model?","o":["PRINCE2 has seven processes: Starting Up, Initiating, Directing, Controlling, Managing Product Delivery, Managing Stage Boundaries, and Closing — organized around management stages with defined go/no-go decision points","PRINCE2 follows the same five-process-group model as PMBOK (Initiating, Planning, Executing, Monitoring, Closing) but with different terminology","PRINCE2 is exclusively an agile framework with sprints and retrospectives at its core","PRINCE2 has three processes: Define, Execute, and Close, governed by a single project board"],"a":0,"e":"PRINCE2''s seven processes reflect its stage-gate philosophy. The Directing process is unique — it governs the project board (not the PM) and is invoked at stage boundaries and exceptions. This is a fundamental distinction from PMBOK''s PM-centric model.","c":"pm:career"},
{"q":"A PM career ladder typically runs from Coordinator to PM to Senior PM to Program Manager to Portfolio Director. What is the primary competency shift between Senior PM and Program Manager?","o":["A Program Manager shifts from delivering a single project to orchestrating multiple interdependent projects toward a strategic outcome, managing dependencies, benefits realization, and a team of PMs rather than a team of contributors","A Program Manager has a higher PMP score and more certifications than a Senior PM","A Program Manager focuses exclusively on budget management while Senior PMs focus on delivery","A Program Manager is a title used only in government and nonprofit organizations; in corporate environments the role is called Director of Projects"],"a":0,"e":"The Senior PM to Program Manager transition is a qualitative shift: from managing work to managing managers and strategy. Program Managers are accountable for benefits realization across a portfolio of related projects — a fundamentally different operating model requiring leadership, political navigation, and strategic alignment skills.","c":"pm:career"},
{"q":"A PM is negotiating a salary for a Senior PM role. The recruiter offers $120,000 and asks if that works. The PM has seven years of experience, a PMP, and has delivered projects worth $10M+. What is the strongest negotiation response?","o":["Express appreciation for the offer, state that based on your research and the scope of projects you''ve led you were targeting $135,000-$140,000, and ask whether there is flexibility — then be silent and wait","Accept the offer immediately because negotiating is risky and could cost you the job","Counter with the exact number $150,000 without explanation to anchor high","Ask for time and come back in two weeks to show you are not desperate"],"a":0,"e":"Salary negotiation best practice: anchor with a range above the target (not the floor), back it with evidence (experience, PMP, project scale), and use silence after the counter. Immediately accepting leaves money on the table. Excessive anchoring without justification reads as unrealistic.","c":"pm:career"},
{"q":"A PM is building a portfolio to apply for senior roles at AI-focused companies. Which artifact most strongly demonstrates project management competency to a hiring committee?","o":["A case study for a delivered project showing original scope, the challenges encountered, the decisions made with rationale, and the measured business outcomes — not just a list of tools used","A list of all certifications held and online courses completed","A GitHub repository of project templates and spreadsheet tools","References from colleagues who can speak to the candidate''s personality and work ethic"],"a":0,"e":"Hiring committees for senior PM roles want evidence of judgment, decision-making under ambiguity, and outcomes. A structured case study (challenge → decisions → results) is the strongest artifact because it demonstrates competency in context. Certification lists and tool inventories show inputs, not capabilities.","c":"pm:career"},
{"q":"How is the AI PM niche differentiated from a general technology PM role, and what specific competencies should a candidate develop to position for AI project management?","o":["AI PM roles require understanding of ML model lifecycle (training, evaluation, deployment, monitoring), data quality and labeling processes, ethical AI and bias risk, and the probabilistic nature of AI outputs — not just software delivery processes","AI PM is identical to general software PM; the only difference is the subject matter of the product","AI PM requires a data science degree and the ability to train machine learning models independently","AI PM is a marketing title with no substantive difference from a traditional senior PM role"],"a":0,"e":"AI projects have unique characteristics: outputs are probabilistic (not deterministic), the development cycle includes data sourcing and labeling, model performance drifts post-deployment, and ethical/bias risks must be managed as first-class project risks. PMs who understand these dynamics command a premium in the AI space.","c":"pm:career"},
{"q":"A PM with five years of experience and no formal certification is competing against a PMP-certified candidate for a program manager role at a Fortune 500 company. What is the strongest differentiator the non-certified PM can present?","o":["A documented track record of managing multiple interdependent projects, quantified business outcomes (revenue, cost reduction, time-to-market), and stakeholder testimonials — demonstrating program-level impact that the certified candidate may not have","Enroll in the PMP exam the week before the interview and list it as ''in progress'' on the resume","Emphasize soft skills and team culture contributions that certifications cannot measure","Highlight the number of projects managed regardless of size or complexity"],"a":0,"e":"Program management is an outcomes role. Quantified business impact — revenue generated, costs avoided, programs delivered — is more persuasive than credentials at the program manager level. The certified candidate has a filter advantage at the screening stage, but the interview and case study are won on demonstrated impact.","c":"pm:career"},
{"q":"A PM wants to transition from a traditional waterfall environment into agile software delivery. Beyond certifications, what is the most effective skill-building strategy?","o":["Volunteer to lead or join a Scrum team on an internal initiative, serve as Scrum Master or Product Owner for one sprint cycle, and document the experience with reflection on what changed from waterfall practice","Complete a 40-hour online agile certification course and list the certification on a resume","Read the Agile Manifesto and three agile books, then apply the concepts mentally to past waterfall projects","Attend an agile conference to network with practitioners"],"a":0,"e":"Experiential learning in agile is essential because agile is a practice, not a theory. Joining or leading a real Scrum team — even on a small internal initiative — builds muscle memory that no course or certification can provide. Documented reflection on the transition demonstrates self-awareness and learning agility to future employers.","c":"pm:career"},
{"q":"Which of the following actions would most directly disqualify a PM candidate from a regulated industry PM role, regardless of their experience and credentials?","o":["Being unable to describe a specific example of how they enforced change control processes or handled a compliance requirement on a past project","Not holding a PRINCE2 certification, which is the industry standard in that sector","Having managed projects exclusively in agile environments when the role is waterfall","Not having direct experience in the exact industry vertical of the hiring company"],"a":0,"e":"In regulated industries (finance, pharma, healthcare, defense), change control and compliance adherence are core PM competencies — not nice-to-haves. A candidate who cannot articulate concrete experience managing governance constraints signals that their experience is insufficient for the regulatory environment.","c":"pm:career"},
{"q":"A PM is preparing for the PMP exam and encounters a question asking whether to take an action that is correct operationally but bypasses the formal change control process. What is always the correct PMP answer for process compliance questions?","o":["Always follow the formal process — get the change approved through the CCB before acting, even if the operational action seems obviously correct","Take the operational action first to protect the project, then document it retroactively","Use judgment: if the sponsor verbally approved it, formal documentation is optional","The correct action depends on project size; large projects require CCB approval, small projects do not"],"a":0,"e":"The PMP exam tests process discipline above operational judgment. PMI''s consistent position: changes must be approved before implementation. ''Ask for forgiveness later'' is never the right PMP answer. This principle applies regardless of how obvious or minor the change seems in the scenario.","c":"pm:career"},
{"q":"A PM is positioning themselves for AI project management roles. Which combination of experiences would most differentiate them in job applications?","o":["Having served as PM on a project that shipped a production ML model, including managing the data pipeline, model validation, and post-launch monitoring phases — plus demonstrated understanding of AI ethics and bias testing","Holding a machine learning engineering degree and two agile certifications","Having managed large software teams and studied AI concepts through online courses","Being a senior PM at a major tech company regardless of whether AI was involved in the projects"],"a":0,"e":"AI PM differentiation comes from proximity to real AI delivery cycles — specifically the non-software-development phases (data, validation, ethics, monitoring) that are unique to AI products. This experience cannot be faked with credentials or general tech PM titles and is highly valued by AI-native employers.","c":"pm:career"},
{"q":"A candidate is asked in a PM interview: ''Tell me about a time you had to deliver bad news to a senior stakeholder.'' What structure best demonstrates PM communication maturity?","o":["Describe the situation and the stakes, explain the process used to verify the facts before communicating, describe how the news was framed with a recommendation and options (not just a problem), and share the outcome including what the stakeholder decided","Describe a time when bad news was delivered and everything worked out fine with no conflict","Focus on how the team rallied together and the stakeholder eventually came around","Explain that the PM always structures communication to avoid delivering bad news by finding solutions first"],"a":0,"e":"The STAR format with executive communication maturity: the strongest answer shows verification before communication (fact-checking), recommendation-based framing (issue + so-what + options), and a documented outcome. Conflict avoidance as a communication strategy is a red flag for senior PM roles.","c":"pm:career"}
]'::jsonb);

-- =============================================================================
-- Verification
-- =============================================================================
SELECT ch.order_index, ch.title, COUNT(qq.id) AS question_count
FROM public.chapters ch
JOIN public.courses co ON ch.course_id = co.id
JOIN public.quizzes qz ON qz.chapter_id = ch.id AND qz.quiz_type = 'chapter_end'
JOIN public.quiz_questions qq ON qq.quiz_id = qz.id
WHERE co.title = 'AI Project Manager & Delivery Leader'
  AND ch.order_index BETWEEN 10 AND 18
GROUP BY ch.order_index, ch.title ORDER BY ch.order_index;
